    public float projectileSpeed = 7f;

    [Tooltip("发射数量")]
    public int projectileCount = 3;

    [Tooltip("敌人搜索半径")]
    public float searchRadius = 10f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (homingProjectilePrefab == null)
        {
            Debug.LogWarning("HomingProjectileSkillEffect: homingProjectilePrefab is null!");
            return;
        }

        // Cache prefab statically for chain reaction (avoids Unity prefab self-reference serialization issue)
        if (BacteriophageProjectile.S_PhagePrefab == null)
            BacteriophageProjectile.S_PhagePrefab = homingProjectilePrefab;

        Vector3 origin = caster.CasterTransform.position;
        float casterAttack = caster.GetAttackStrength();
        float totalDamage = casterAttack * damageMultiplier;

        var enemies = FindNearestEnemies(origin, searchRadius, projectileCount);

        if (enemies.Count == 0)
        {
            Fire(origin, null, totalDamage, casterAttack, damageMultiplier, ownerType);
            return;
        }

        foreach (var enemy in enemies)
        {
            Fire(origin, enemy, totalDamage, casterAttack, damageMultiplier, ownerType);
        }
    }

    private List<Transform> FindNearestEnemies(Vector3 origin, float radius, int maxCount)
    {
        var hits = Physics2D.OverlapCircleAll(origin, radius);
        var result = new List<(Transform t, float d)>();

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            var ec = hit.GetComponent<EnemyCore>();
            if (ec == null || ec.IsDead) continue;
            float d = Vector3.Distance(origin, hit.transform.position);
            result.Add((hit.transform, d));
        }

        result.Sort((a, b) => a.d.CompareTo(b.d));

        var final = new List<Transform>();
        int count = Mathf.Min(maxCount, result.Count);
        for (int i = 0; i < count; i++)
            final.Add(result[i].t);
        return final;
    }

    private void Fire(Vector3 origin, Transform target, float totalDamage,
        float casterAttackStrength, float damageMultiplier,
        Projectile.OwnerType ownerType)
    {
        GameObject go = Instantiate(homingProjectilePrefab, origin, Quaternion.identity);
        var hp = go.GetComponent<IHomingProjectile>();
        if (hp == null)
        {
            Debug.LogWarning($"HomingProjectileSkillEffect: prefab '{go.name}' does not implement IHomingProjectile!");
            return;
        }
        hp.Initialize(target, projectileSpeed, casterAttackStrength,
            damageMultiplier, totalDamage, ownerType);
    }
}

using UnityEngine;

/// <summary>
/// 侵蚀投射物命中逻辑 — 命中敌人后弹出二选一弹窗（吞噬 / 同化）。
/// 飞行由 Projectile 组件（ProjectileSkillEffect 自动添加）负责。
/// 挂载在 ErodeProjectile 预制体上，与 Projectile 组件共存。
/// </summary>
public class ErodeProjectile : MonoBehaviour
{
    [Header("特效")]
    [SerializeField] private GameObject hitEffectPrefab;

    private void OnTriggerEnter2D(Collider2D other)
    {
        // 只命中敌人
        if (!other.CompareTag("Enemy")) return;

        IEnemy enemy = other.GetComponent<IEnemy>();
        if (enemy == null) return;

        // 获取玩家技能管理器
        PlayerSkillManager player = FindPlayerSkillManager();
        if (player == null) return;

        var enemySkills = enemy.SkillInstances;
        bool hasSkills = enemySkills != null && enemySkills.Count > 0;

        // 暂停 + 弹窗
        Time.timeScale = 0f;

        EnemyCore core = enemy as EnemyCore;
        ErodeChoicePopupManager popup = ErodeChoicePopupManager.Instance;
        if (popup != null && core != null)
        {
            popup.ShowPopup(core, hasSkills, enemySkills, player, () => Time.timeScale = 1f);
        }
        else
        {
            Time.timeScale = 1f;
        }
    }

    private void OnDestroy()
    {
        // 生成命中爆发特效
        if (hitEffectPrefab != null)
        {
            Instantiate(hitEffectPrefab, transform.position, Quaternion.identity);
        }

        // 将拖尾粒子子物体分离并定时销毁
        var trail = transform.Find("TrailParticles");
        if (trail != null)
        {
            trail.SetParent(null);
            var ps = trail.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                ps.Stop(true, ParticleSystemStopBehavior.StopEmitting);
                Destroy(trail.gameObject, ps.main.startLifetime.constantMax + 1f);
            }
            else
            {
                Destroy(trail.gameObject, 2f);
            }
        }
    }

    private static PlayerSkillManager FindPlayerSkillManager()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<PlayerSkillManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 范围伤害技能效果：以施法者或目标点为中心造成圆形范围伤害。
/// 右键 -> Create -> Game -> Skill Effect -> AoE Damage
/// </summary>
[CreateAssetMenu(fileName = "AoEEffect", menuName = "Game/Skill Effect/AoE Damage")]
public class AoESkillEffect : SkillEffectBase
{
    [Header("范围配置")]
    [Tooltip("伤害半径")]
    public float radius = 3f;

    [Tooltip("是否以施法者为中心（否则以施法方向前方2单位处为中心）")]
    public bool centeredOnCaster = true;

    [Tooltip("打击特效预制体（可选）")]
    public GameObject impactVfx;

    [Header("预警（可选）")]
    [Tooltip("预警时间（秒），>0 则延迟生效并播放预警特效")]
    public float warningDuration;

    [Tooltip("预警特效（可选，须配合 warningDuration 使用）")]
    public GameObject warningVfx;

    [Header("眩晕（可选）")]
    [Tooltip("玩家被击中后眩晕时间（秒），0=不眩晕")]
    public float stunDuration;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        Vector2 center = centeredOnCaster
            ? (Vector2)caster.CasterTransform.position
            : (Vector2)caster.CasterTransform.position + direction * 2f;

        float damage = caster.GetAttackStrength() * damageMultiplier;

        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono != null)
            mono.StartCoroutine(DelayedExecute(center, damage, ownerType));
        else
            ApplyDamage(center, damage, ownerType);
    }

    private System.Collections.IEnumerator DelayedExecute(Vector2 center,
        float damage, Projectile.OwnerType ownerType)
    {
        if (warningVfx != null)
            Object.Instantiate(warningVfx, center, Quaternion.identity);

        if (warningDuration > 0f)
            yield return new WaitForSeconds(warningDuration);

        ApplyDamage(center, damage, ownerType);
    }

    private void ApplyDamage(Vector2 center, float damage, Projectile.OwnerType ownerType)
    {
        if (impactVfx != null)
            Object.Instantiate(impactVfx, center, Quaternion.identity);

        Collider2D[] hits = Physics2D.OverlapCircleAll(center, radius);
        string enemyTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";

        foreach (var hit in hits)
        {
            if (!hit.CompareTag(enemyTag)) continue;
            if (hit.TryGetComponent<IDamageable>(out var d))
                d.TakeDamage(damage);

            if (stunDuration > 0f && hit.CompareTag("Player")
                && hit.TryGetComponent<PlayerController>(out var pc))
                pc.StartCoroutine(StunRoutine(pc, stunDuration));
        }
    }

    private static System.Collections.IEnumerator StunRoutine(PlayerController pc, float duration)
    {
        pc.InputLocked = true;
        yield return new WaitForSeconds(duration);
        pc.InputLocked = false;
    }
}

using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件: (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 移动组件：封装 Rigidbody2D 操作与视线检测缓存。
///
/// 速度数据源： EnemyConfig.patrolSpeed / EnemyConfig.chaseSpeed
///             由状态机在 Enter 时写入 MoveSpeed，组件本身不做初始化。
/// </summary>
[RequireComponent(typeof(Rigidbody2D))]
public class EnemyMovement : MonoBehaviour
{
    /// <summary>运行时当前速度（由状态机从 EnemyConfig 赋值，不在 Inspector 设置）</summary>
    [HideInInspector]
    public float MoveSpeed = 2f;

    private Rigidbody2D _rb;
    private float _nextSightCheckTime;
    private bool _cachedHasLineOfSight;
    private bool _wasInDetectionRange = false;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (_rb != null) _rb.freezeRotation = true;
    }

    public void Stop()
    {
        if (_rb != null) _rb.velocity = Vector2.zero;
    }

    public void MoveTowardsPosition(Vector2 target, float speedMultiplier = 1f)
    {
        if (_rb == null) return;
        Vector2 dir = (target - (Vector2)transform.position).normalized;
        _rb.velocity = dir * MoveSpeed * speedMultiplier;
    }

    public void SetVelocity(Vector2 vel)
    {
        if (_rb == null) return;
        _rb.velocity = vel;
    }

    /// <summary>直接传送到目标位置（通过 Rigidbody2D.position）</summary>
    public void Teleport(Vector2 targetPos)
    {
        if (_rb != null)
        {
            _rb.velocity = Vector2.zero;
            _rb.position = targetPos;
        }
        else
        {
            transform.position = targetPos;
        }
    }

    /// <summary>
    /// 带缓存的视线检测。调用时会基于 interval 减少 Linecast 次数。
    /// </summary>
    public bool HasLineOfSight(Vector2 targetPosition, float detectionRange, float sightCheckInterval = 0.2f)
    {
        float sqrDistance = ((Vector2)transform.position - targetPosition).sqrMagnitude;
        bool inRange = sqrDistance <= detectionRange * detectionRange;

        if (!inRange)
        {
            _wasInDetectionRange = false;
            _cachedHasLineOfSight = false;
            return false;
        }

        if (!_wasInDetectionRange)
        {
            _nextSightCheckTime = 0f; // force immediate check
            _wasInDetectionRange = true;
        }

        if (Time.time >= _nextSightCheckTime)
        {
            _nextSightCheckTime = Time.time + sightCheckInterval;
            RaycastHit2D hit = Physics2D.Linecast(transform.position, targetPosition);
            _cachedHasLineOfSight = hit.collider == null || !hit.collider.CompareTag("Wall");
        }

        return _cachedHasLineOfSight;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 所有对外系统（Spawner、技能效果等）应依赖 IEnemy 接口。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    // 子组件
    public EnemyHealth Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }
    public IAttackBehavior AttackBehavior { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances => SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    /// <summary>全局静态事件 — 任意敌人死亡时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemyDied;

    private void Awake()
    {
        Health = GetComponent<EnemyHealth>();
        Movement = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();
        AttackBehavior = GetComponent<IAttackBehavior>();

        if (Health == null) Health = gameObject.AddComponent<EnemyHealth>();
        if (Movement == null) Movement = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        // ═══ 单一数据源：EnemyConfig → EnemyCore → 各组件 ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth = config.maxHealth;
                Health.Initialize();
            }

            if (Movement != null)
                Movement.MoveSpeed = config.patrolSpeed;

            if (SkillManager != null)
                SkillManager.InitializeFromLibrary(config.skillLibrary);
        }
        else if (Health != null)
        {
            // 无 config 时，允许组件自身的 MaxHealth 作为默认值
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                OnAnyEnemyDied?.Invoke(this);
                // 切换到死亡状态
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        if (player != null) PlayerTarget = player.transform;

        // 启动默认状态（若存在巡逻点则 Patrol，否则 Idle）
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        // 优先从 MeleeAttack 组件读取伤害值
        if (AttackBehavior is MeleeAttack melee)
            return melee.damage;
        if (AttackBehavior is RangedAttack ranged)
            return ranged.damage;
        return 10f;
    }

    /// <summary>
    /// 施法者阵营：被同化后为 Player（技能命中 Enemy），否则为 Enemy（技能命中 Player）。
    /// </summary>
    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    // ---------- 同化 ----------
    /// <summary>
    /// 将被侵蚀的敌人转化为玩家的随从。
    /// - 改 tag 为 Player（让其他敌人的攻击能命中此随从）
    /// - 禁用原状态机，由 EnemyFollower 接管 AI
    /// - 清除旧的死亡事件，由 EnemyFollower 处理死亡
    /// </summary>
    public void Assimilate(Transform playerTarget)
    {
        // 1. 标记已同化（房间/生成器通过 OnAssimilated 事件从存活列表移除）
        IsAssimilated = true;

        // 2. 清除旧的死亡订阅（由 EnemyFollower 接管死亡处理）
        if (Health != null)
            Health.ClearOnDied();

        // 3. 通知外部系统：此敌人不再是敌人
        OnAssimilated?.Invoke(this);

        // 4. 改 tag，使敌人攻击能命中此随从
        gameObject.tag = "Player";

        // 5. 禁用原有状态机
        if (StateMachine != null)
            StateMachine.enabled = false;

        // 6. 停止当前移动
        Movement?.Stop();

        // 7. 添加并激活随从组件
        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        // 8. 更新玩家引用（供技能方向等使用）
        PlayerTarget = playerTarget;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
        else
        {
            // 预热对象池，避免首帧给卡
            ProjectilePool.Prewarm(bulletPrefab, 10);
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 从对象池获取子弹
        GameObject bullet = ProjectilePool.Get(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player, gameObject);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

