args.script:
using System.IO;
using UnityEditor;
using UnityEngine;

// ── 1. 创建文件夹 ──
string skillDataDir = "Assets/Resources/Skills/Data/AxonBlock";
if (!AssetDatabase.IsValidFolder(skillDataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "AxonBlock");

// ── 2. 查找 Shader ──
Shader waveShader = Shader.Find("Custom/AxonBlockWave");
Shader overlayShader = Shader.Find("Custom/AxonBlockOverlay");
if (waveShader == null) { Debug.LogError("未找到 Custom/AxonBlockWave shader!"); return; }
if (overlayShader == null) { Debug.LogError("未找到 Custom/AxonBlockOverlay shader!"); return; }

// ── 3. 创建波纹材质 ──
string waveMatPath = "Assets/Materials/AxonBlockWave.mat";
Material waveMat = AssetDatabase.LoadAssetAtPath<Material>(waveMatPath);
if (waveMat == null)
{
    waveMat = new Material(waveShader);
    waveMat.SetFloat("_CurrentRadius", 0f);
    waveMat.SetFloat("_MaxRadius", 10f);
    waveMat.SetFloat("_Progress", 0f);
    waveMat.SetFloat("_Fade", 1f);
    waveMat.SetFloat("_RingWidth", 0.8f);
    waveMat.SetFloat("_Distortion", 0.15f);
    waveMat.SetColor("_Color", new Color(0.2f, 0.8f, 1.0f, 1.0f));
    waveMat.SetColor("_ColorInner", new Color(0.6f, 0.9f, 1.0f, 0.6f));
    AssetDatabase.CreateAsset(waveMat, waveMatPath);
    Debug.Log($"创建波纹材质: {waveMatPath}");
}
else
{
    waveMat.shader = waveShader;
    EditorUtility.SetDirty(waveMat);
    Debug.Log($"已更新波纹材质: {waveMatPath}");
}

// ── 4. 创建覆盖层材质 ──
string overlayMatPath = "Assets/Materials/AxonBlockOverlay.mat";
Material overlayMat = AssetDatabase.LoadAssetAtPath<Material>(overlayMatPath);
if (overlayMat == null)
{
    overlayMat = new Material(overlayShader);
    overlayMat.SetFloat("_Progress", 0f);
    overlayMat.SetVector("_WaveCenter", new Vector4(0, 0, 0, 0));
    overlayMat.SetFloat("_Distortion", 0.5f);
    overlayMat.SetColor("_Tint", new Color(0.15f, 0.35f, 0.6f, 0.2f));
    overlayMat.SetFloat("_NoiseScale", 15f);
    overlayMat.SetFloat("_NoiseSpeed", 2f);
    AssetDatabase.CreateAsset(overlayMat, overlayMatPath);
    Debug.Log($"创建覆盖层材质: {overlayMatPath}");
}
else
{
    overlayMat.shader = overlayShader;
    EditorUtility.SetDirty(overlayMat);
    Debug.Log($"已更新覆盖层材质: {overlayMatPath}");
}

// ── 5. 创建 AxonBlockEffect.asset (SkillEffectBase SO) ──
string effectPath = skillDataDir + "/AxonBlockEffect.asset";
AxonBlockSkillEffect effectSO = AssetDatabase.LoadAssetAtPath<AxonBlockSkillEffect>(effectPath);
if (effectSO == null)
{
    effectSO = ScriptableObject.CreateInstance<AxonBlockSkillEffect>();
    AssetDatabase.CreateAsset(effectSO, effectPath);
    Debug.Log($"创建效果资产: {effectPath}");
}

// 用 SerializedObject 设置字段（包括 private serialized fields）
SerializedObject so = new SerializedObject(effectSO);
so.FindProperty("_freezeDuration").floatValue = 2f;
so.FindProperty("_waveSpeed").floatValue = 8f;
so.FindProperty("_maxRadius").floatValue = 10f;
so.FindProperty("_waveMaterial").objectReferenceValue = waveMat;
so.FindProperty("_overlayMaterial").objectReferenceValue = overlayMat;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effectSO);
Debug.Log("已配置 AxonBlockEffect 参数");

// ── 6. 创建 AxonBlock.asset (SkillData SO) ──
string skillDataPath = skillDataDir + "/AxonBlock.asset";
SkillData skillData = AssetDatabase.LoadAssetAtPath<SkillData>(skillDataPath);
if (skillData == null)
{
    skillData = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(skillData, skillDataPath);
    Debug.Log($"创建技能数据: {skillDataPath}");
}

skillData.skillId = "axon_block";
skillData.skillName = "轴突传导阻滞";
skillData.description = "释放一道圆形波从自身处扩散出去，波纹触及的敌人和子弹被时停2秒。技能期间可自由移动，但普攻或使用其他技能会使时停失效。";
skillData.cooldown = 12f;
skillData.castRange = 10f;
skillData.damageMultiplier = 0f; // 无伤害
skillData.maxLevel = 3;
skillData.skillEffect = effectSO;
skillData.icon = null; // 图标后续生成
EditorUtility.SetDirty(skillData);
Debug.Log("已配置 AxonBlock SkillData 参数");

// ── 7. 注册到 SkillLibrary ──
SkillLibrary library = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
if (library != null)
{
    // 检查是否已注册
    bool found = false;
    var allSkills = library.AllSkills;
    foreach (var s in allSkills)
    {
        if (s != null && s.skillId == "axon_block")
        {
            found = true;
            break;
        }
    }

    if (!found)
    {
        // 用反射访问 private _allSkills 列表
        var field = typeof(SkillLibrary).GetField("_allSkills",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        if (field != null)
        {
            var list = field.GetValue(library) as System.Collections.Generic.List<SkillData>;
            if (list != null)
            {
                list.Add(skillData);
                Debug.Log("已将轴突传导阻滞注册到 SkillLibrary");
            }
        }
    }
    else
    {
        Debug.Log("轴突传导阻滞已在 SkillLibrary 中，跳过注册");
    }
    EditorUtility.SetDirty(library);
}
else
{
    Debug.LogError("未找到 SkillLibrary.asset!");
}

// ── 8. 保存 ──
AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 轴突传导阻滞技能资产创建完成 ===");

