    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    /// <summary>是否被时停冻结</summary>
    public bool IsFrozen { get; private set; }
    private float _frozenLifetimeRemain;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;
        IsFrozen = false;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>冻结投射物（停止移动+暂停生命周期）</summary>
    public void Freeze()
    {
        if (!_isInitialized || IsFrozen) return;
        IsFrozen = true;
        // 记录剩余生命时间并取消自动回收
        _frozenLifetimeRemain = Mathf.Max(lifeTime * 0.5f, 1f);
        CancelInvoke(nameof(ReturnToPool));
    }

    /// <summary>解冻投射物，恢复移动和生命周期</summary>
    public void Unfreeze()
    {
        if (!_isInitialized || !IsFrozen) return;
        IsFrozen = false;
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), _frozenLifetimeRemain);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized || IsFrozen) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 时停管理器：轴突传导阻滞技能的核心运行时组件。
/// 管理被冻结的敌人和子弹，处理时停计时与取消机制。
/// 由 AxonBlockSkillEffect 创建临时 GameObject 挂载本组件。
/// </summary>
public class TimeStopManager : MonoBehaviour
{
    [Header("时停参数")]
    [Tooltip("时停持续时间（秒）")]
    [SerializeField] private float _duration = 2f;
    [Tooltip("取消监听宽限期（秒），技能释放后此时间内不响应取消）")]
    [SerializeField] private float _cancelGracePeriod = 0.3f;

    // ---------- 运行时状态 ----------
    private float _timer;
    private bool _isActive;
    private bool _listeningForCancel;

    // 冻结实体集合
    private readonly HashSet<EnemyCore> _frozenEnemies = new();
    private readonly HashSet<Projectile> _frozenProjectiles = new();

    // 玩家引用（用于取消监听）
    private PlayerCombat _playerCombat;
    private PlayerSkillManager _playerSkillManager;

    // 视觉
    private SpriteRenderer _waveRenderer;
    private Material _waveMaterial;
    private Material _overlayMaterial;
    private MeshRenderer _overlayRenderer;
    private GameObject _overlayObject;
    private Vector2 _origin;
    private float _waveSpeed;
    private float _maxRadius;

    /// <summary>是否正在时停中</summary>
    public bool IsActive => _isActive;

    /// <summary>
    /// 激活时停。
    /// </summary>
    public void Activate(Vector2 origin, float duration, float waveSpeed, float maxRadius,
                          Material waveMat, Material overlayMat)
    {
        _origin = origin;
        _duration = duration;
        _waveSpeed = waveSpeed;
        _maxRadius = maxRadius;
        _timer = duration;
        _isActive = true;
        _listeningForCancel = false;

        // ── 创建波纹视觉 ──
        CreateWaveVisual(origin, waveMat);

        // ── 创建全屏覆盖层 ──
        CreateOverlay(overlayMat);

        // ── 查找玩家组件用于取消监听 ──
        var playerGO = GameObject.FindGameObjectWithTag("Player");
        if (playerGO != null)
        {
            _playerCombat = playerGO.GetComponent<PlayerCombat>();
            _playerSkillManager = playerGO.GetComponent<PlayerSkillManager>();
        }

        // ── 延迟开启取消监听 ──
        StartCoroutine(EnableCancelListeningAfterDelay(_cancelGracePeriod));
    }

    // ──────────────────────────────────────────────
    //  冻结 / 解冻
    // ──────────────────────────────────────────────

    /// <summary>冻结敌人（波纹触及后调用）</summary>
    public void FreezeEnemy(EnemyCore enemy)
    {
        if (!_isActive || enemy == null || _frozenEnemies.Contains(enemy)) return;
        if (enemy.IsDead) return;

        // 停止移动并禁用 AI 组件
        if (enemy.Movement != null)
        {
            enemy.Movement.Stop();
            enemy.Movement.enabled = false;
        }
        if (enemy.StateMachine != null)
            enemy.StateMachine.enabled = false;
        if (enemy.SkillManager != null)
            enemy.SkillManager.enabled = false;

        _frozenEnemies.Add(enemy);
    }

    /// <summary>冻结子弹（波纹触及后调用）</summary>
    public void FreezeProjectile(Projectile proj)
    {
        if (!_isActive || proj == null || _frozenProjectiles.Contains(proj)) return;
        proj.Freeze();
        _frozenProjectiles.Add(proj);
    }

    /// <summary>解冻所有实体并清理</summary>
    private void UnfreezeAll()
    {
        foreach (var enemy in _frozenEnemies)
        {
            if (enemy == null) continue;
            if (enemy.StateMachine != null) enemy.StateMachine.enabled = true;
            if (enemy.Movement != null) enemy.Movement.enabled = true;
            if (enemy.SkillManager != null) enemy.SkillManager.enabled = true;
        }

        foreach (var proj in _frozenProjectiles)
        {
            if (proj != null) proj.Unfreeze();
        }

        _frozenEnemies.Clear();
        _frozenProjectiles.Clear();
    }

    // ──────────────────────────────────────────────
    //  取消机制
    // ──────────────────────────────────────────────

    private IEnumerator EnableCancelListeningAfterDelay(float delay)
    {
        yield return new WaitForSeconds(delay);
        if (!_isActive) yield break;

        _listeningForCancel = true;
        if (_playerCombat != null)
            _playerCombat.OnShoot += OnPlayerAttack;
        if (_playerSkillManager != null)
            _playerSkillManager.OnSkillCast += OnPlayerSkillCast;
    }

    private void OnPlayerAttack(Vector2 dir, float spd, float dmg)
    {
        if (_listeningForCancel) CancelTimeStop();
    }

    private void OnPlayerSkillCast(int slot, SkillData data)
    {
        if (_listeningForCancel) CancelTimeStop();
    }

    /// <summary>提前取消时停（普攻或释放其他技能时触发）</summary>
    public void CancelTimeStop()
    {
        if (!_isActive) return;
        _timer = 0f;
    }

    private void EndTimeStop()
    {
        if (!_isActive) return;

        // 取消事件订阅
        if (_playerCombat != null)
            _playerCombat.OnShoot -= OnPlayerAttack;
        if (_playerSkillManager != null)
            _playerSkillManager.OnSkillCast -= OnPlayerSkillCast;

        _isActive = false;
        _listeningForCancel = false;

        // 解冻所有实体
        UnfreezeAll();

        // 淡出视觉并销毁
        StartCoroutine(FadeOutAndDestroy());
    }

    // ──────────────────────────────────────────────
    //  每帧更新
    // ──────────────────────────────────────────────

    private void Update()
    {
        if (!_isActive)
        {
            // 更新淡出中的视觉
            if (_waveMaterial != null)
                _waveMaterial.SetFloat("_Fade", Mathf.MoveTowards(_waveMaterial.GetFloat("_Fade"), 0f, Time.deltaTime * 4f));
            return;
        }

        _timer -= Time.deltaTime;

        // 更新波纹 shader 参数
        float elapsed = _duration - _timer;
        float currentRadius = Mathf.Min(elapsed * _waveSpeed, _maxRadius);

        if (_waveMaterial != null)
        {
            _waveMaterial.SetFloat("_CurrentRadius", currentRadius);
            _waveMaterial.SetFloat("_MaxRadius", _maxRadius);
            _waveMaterial.SetFloat("_Progress", Mathf.Clamp01(elapsed / _duration));
        }

        if (_overlayMaterial != null)
        {
            _overlayMaterial.SetFloat("_Progress", Mathf.Clamp01(elapsed / _duration));
            _overlayMaterial.SetVector("_WaveCenter", _origin);
        }

        // 覆盖层跟随相机
        if (_overlayObject != null && Camera.main != null)
        {
            var camPos = Camera.main.transform.position;
            _overlayObject.transform.position = new Vector3(camPos.x, camPos.y, 0f);
        }

        if (_timer <= 0f)
        {
            EndTimeStop();
        }
    }

    // ──────────────────────────────────────────────
    //  视觉创建
    // ──────────────────────────────────────────────

    private void CreateWaveVisual(Vector2 origin, Material waveMat)
    {
        var waveGO = new GameObject("AxonBlockWave");
        waveGO.transform.SetParent(transform);
        waveGO.transform.position = origin;
        waveGO.transform.localScale = Vector3.one;

        _waveRenderer = waveGO.AddComponent<SpriteRenderer>();
        _waveMaterial = new Material(waveMat);
        _waveRenderer.material = _waveMaterial;
        _waveRenderer.sortingOrder = 100; // 在最上层
        _waveRenderer.color = Color.white;

        // 缩放设为最大半径的两倍（shader 内部用 UV 计算环）
        float scale = _maxRadius * 2f;
        waveGO.transform.localScale = new Vector3(scale, scale, 1f);
    }

    private void CreateOverlay(Material overlayMat)
    {
        var cam = Camera.main;
        if (cam == null) return;

        _overlayObject = new GameObject("AxonBlockOverlay");
        _overlayObject.transform.SetParent(transform);

        _overlayRenderer = _overlayObject.AddComponent<MeshRenderer>();
        _overlayRenderer.sortingOrder = 200;

        var filter = _overlayObject.AddComponent<MeshFilter>();
        // 全屏四边形
        filter.mesh = CreateFullscreenQuad(cam);

        _overlayMaterial = new Material(overlayMat);
        _overlayRenderer.material = _overlayMaterial;
        _overlayMaterial.SetFloat("_Progress", 0f);

        // 跟随相机
        _overlayObject.transform.position = new Vector3(cam.transform.position.x, cam.transform.position.y, 0f);
        _overlayObject.transform.rotation = cam.transform.rotation;
    }

    private IEnumerator FadeOutAndDestroy()
    {
        float fadeTime = 0.4f;
        float elapsed = 0f;

        while (elapsed < fadeTime)
        {
            elapsed += Time.deltaTime;
            float t = 1f - elapsed / fadeTime;

            if (_waveMaterial != null)
                _waveMaterial.SetFloat("_Fade", t);
            if (_overlayMaterial != null)
                _overlayMaterial.SetFloat("_Progress", t * 0.3f);

            yield return null;
        }

        Destroy(gameObject);
    }

    // ──────────────────────────────────────────────
    //  工具
    // ──────────────────────────────────────────────

    private static Mesh CreateFullscreenQuad(Camera cam)
    {
        float height = cam.orthographicSize * 2f;
        float width = height * cam.aspect;

        Mesh mesh = new Mesh();
        mesh.vertices = new Vector3[]
        {
            new(-width / 2f, -height / 2f, 1f),
            new( width / 2f, -height / 2f, 1f),
            new( width / 2f,  height / 2f, 1f),
            new(-width / 2f,  height / 2f, 1f),
        };
        mesh.uv = new Vector2[]
        {
            new(0f, 0f), new(1f, 0f), new(1f, 1f), new(0f, 1f),
        };
        mesh.triangles = new int[] { 0, 2, 1, 0, 3, 2 };
        mesh.RecalculateNormals();
        return mesh;
    }

    private void OnDestroy()
    {
        // 确保解冻（防止意外销毁时实体卡死）
        if (_isActive)
        {
            if (_playerCombat != null)
                _playerCombat.OnShoot -= OnPlayerAttack;
            if (_playerSkillManager != null)
                _playerSkillManager.OnSkillCast -= OnPlayerSkillCast;
            UnfreezeAll();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 轴突传导阻滞 — 扩散波碰撞检测组件。
/// 挂载在 TimeStopManager 子对象上，逐帧用 OverlapCircleAll 检测波纹当前半径触及的
/// 敌人（EnemyCore）和子弹（Projectile），注册到 TimeStopManager 冻结。
/// </summary>
public class AxonBlockWave : MonoBehaviour
{
    private TimeStopManager _manager;
    private Vector2 _origin;
    private float _waveSpeed;
    private float _maxRadius;
    private float _elapsed;

    // 已检测过的实体（避免重复冻结）
    private readonly HashSet<int> _checkedEntityIds = new();

    // 检测间隔（每帧检测性能开销大，可降频）
    private float _checkInterval = 0.02f;
    private float _nextCheckTime;

    /// <summary>
    /// 初始化扩散波。
    /// </summary>
    public void Initialize(TimeStopManager manager, Vector2 origin, float waveSpeed, float maxRadius)
    {
        _manager = manager;
        _origin = origin;
        _waveSpeed = waveSpeed;
        _maxRadius = maxRadius;
        _elapsed = 0f;
        _nextCheckTime = 0f;
    }

    private void Update()
    {
        if (_manager == null || !_manager.IsActive)
        {
            return;
        }

        _elapsed += Time.deltaTime;
        float currentRadius = Mathf.Min(_elapsed * _waveSpeed, _maxRadius);

        // 波纹扩张完毕后停止检测
        if (currentRadius >= _maxRadius)
        {
            enabled = false;
            return;
        }

        // 降频检测
        if (Time.time < _nextCheckTime) return;
        _nextCheckTime = Time.time + _checkInterval;

        DetectEntities(currentRadius);
    }

    private void DetectEntities(float radius)
    {
        // 用稍宽的环形带检测：当前半径前后各 1 单位的范围
        float innerRadius = Mathf.Max(0f, radius - 1f);
        float outerRadius = radius + 1f;

        // ── 检测敌人 ──
        Collider2D[] hits = Physics2D.OverlapCircleAll(_origin, outerRadius);
        foreach (var hit in hits)
        {
            if (hit == null) continue;

            int id = hit.GetInstanceID();
            if (_checkedEntityIds.Contains(id)) continue;

            // 敌人
            var enemy = hit.GetComponent<EnemyCore>();
            if (enemy != null && !enemy.IsDead)
            {
                float dist = Vector2.Distance(_origin, hit.transform.position);
                if (dist <= outerRadius && dist >= innerRadius)
                {
                    _manager.FreezeEnemy(enemy);
                    _checkedEntityIds.Add(id);
                }
                continue;
            }

            // 子弹
            var proj = hit.GetComponent<Projectile>();
            if (proj != null)
            {
                float dist = Vector2.Distance(_origin, hit.transform.position);
                if (dist <= outerRadius && dist >= innerRadius)
                {
                    _manager.FreezeProjectile(proj);
                    _checkedEntityIds.Add(id);
                }
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 轴突传导阻滞技能效果。
/// 从施法者处释放一道圆形波扩散出去，波纹触及的敌人和子弹被时停。
/// 技能期间发动者可自由移动；普攻或使用其他技能会提前取消时停。
/// 右键 -> Create -> Game -> Skill Effect -> Axon Block
/// </summary>
[CreateAssetMenu(fileName = "AxonBlockEffect", menuName = "Game/Skill Effect/Axon Block")]
public class AxonBlockSkillEffect : SkillEffectBase
{
    [Header("时停配置")]
    [Tooltip("时停持续时间（秒）")]
    [SerializeField] private float _freezeDuration = 2f;

    [Header("波纹配置")]
    [Tooltip("波纹扩散速度（单位/秒）")]
    [SerializeField] private float _waveSpeed = 8f;
    [Tooltip("波纹最大半径")]
    [SerializeField] private float _maxRadius = 10f;

    [Header("视觉材质")]
    [Tooltip("波纹材质（使用 AxonBlockWave shader）")]
    [SerializeField] private Material _waveMaterial;
    [Tooltip("全屏覆盖材质（使用 AxonBlockOverlay shader）")]
    [SerializeField] private Material _overlayMaterial;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        Vector2 origin = caster.CasterTransform.position;

        // 如果已有时停在进行中，不重复触发
        var existing = FindAnyObjectByType<TimeStopManager>();
        if (existing != null && existing.IsActive) return;

        // 创建时停管理器
        var go = new GameObject("AxonBlockTimeStop");
        var manager = go.AddComponent<TimeStopManager>();

        // 添加波纹检测组件
        var wave = go.AddComponent<AxonBlockWave>();
        wave.Initialize(manager, origin, _waveSpeed, _maxRadius);

        // 激活时停
        manager.Activate(origin, _freezeDuration, _waveSpeed, _maxRadius,
                          _waveMaterial, _overlayMaterial);
    }
}

