    var icons = AssetDatabase.FindAssets("t:Sprite", new[] { "Assets/Resources/Skills/Data/AxonBlock" });
    if (icons.Length > 0)
    {
        var path = AssetDatabase.GUIDToAssetPath(icons[0]);
