using UnityEditor;
using UnityEngine;

// ── 1. 更新材质 shader 引用 ──
Material waveMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/AxonBlockWave.mat");
if (waveMat != null)
{
    Shader newWaveShader = Shader.Find("Custom/DiffusionWave");
    if (newWaveShader != null)
    {
        waveMat.shader = newWaveShader;
        EditorUtility.SetDirty(waveMat);
        Debug.Log("AxonBlockWave.mat → shader: Custom/DiffusionWave");
    }
    else Debug.LogError("Custom/DiffusionWave shader 未找到!");
}

Material overlayMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/AxonBlockOverlay.mat");
if (overlayMat != null)
{
    Shader newOverlayShader = Shader.Find("Custom/WaveOverlay");
    if (newOverlayShader != null)
    {
        overlayMat.shader = newOverlayShader;
        EditorUtility.SetDirty(overlayMat);
        Debug.Log("AxonBlockOverlay.mat → shader: Custom/WaveOverlay");
    }
    else Debug.LogError("Custom/WaveOverlay shader 未找到!");
}

// ── 2. 更新 AxonBlockEffect.asset 引用 WaveSkillEffect ──
string effectPath = "Assets/Resources/Skills/Data/AxonBlock/AxonBlockEffect.asset";
var effectSO = AssetDatabase.LoadAssetAtPath<SkillEffectBase>(effectPath);
if (effectSO == null)
{
    // 旧引用已失效（AxonBlockSkillEffect 已删除），需要重新创建
    var newEffect = ScriptableObject.CreateInstance<WaveSkillEffect>();
    AssetDatabase.CreateAsset(newEffect, effectPath);
    effectSO = newEffect;
    Debug.Log("重新创建 AxonBlockEffect.asset 为 WaveSkillEffect");
}
else if (effectSO is WaveSkillEffect)
{
    Debug.Log("AxonBlockEffect.asset 已是 WaveSkillEffect");
}
else
{
    // 类型不匹配，删除旧的重新创建
    AssetDatabase.DeleteAsset(effectPath);
    var newEffect = ScriptableObject.CreateInstance<WaveSkillEffect>();
    AssetDatabase.CreateAsset(newEffect, effectPath);
    effectSO = newEffect;
    Debug.Log("替换 AxonBlockEffect.asset 为 WaveSkillEffect");
}

// 配置参数
SerializedObject so = new SerializedObject(effectSO);
so.FindProperty("_waveSpeed").floatValue = 25f;
so.FindProperty("_maxRadius").floatValue = 10f;
so.FindProperty("_damage").floatValue = 0f;
so.FindProperty("_freezeDuration").floatValue = 2f;
so.FindProperty("_freezeProjectiles").boolValue = true;
so.FindProperty("_cancelOnAttack").boolValue = true;
so.FindProperty("_cancelOnSkillCast").boolValue = true;
so.FindProperty("_cancelGracePeriod").floatValue = 0.3f;
so.FindProperty("_waveMaterial").objectReferenceValue = waveMat;
so.FindProperty("_overlayMaterial").objectReferenceValue = overlayMat;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effectSO);
Debug.Log("已配置 WaveSkillEffect 参数 (waveSpeed=25)");

// ── 3. 更新 SkillData 引用 ──
SkillData skillData = AssetDatabase.LoadAssetAtPath<SkillData>("Assets/Resources/Skills/Data/AxonBlock/AxonBlock.asset");
if (skillData != null)
{
    skillData.skillEffect = effectSO;
    EditorUtility.SetDirty(skillData);
    Debug.Log("AxonBlock.asset → skillEffect 已更新");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 资产引用更新完成 ===");

