using UnityEditor;
using UnityEngine;

string src = "Assets/Prefabs/Projectiles";
string dst = "Assets/Prefabs/SkillAsset";

if (AssetDatabase.LoadAssetAtPath<Object>(dst) != null)
{
    Debug.Log("目标路径已存在，跳过重命名");
    return;
}

string error = AssetDatabase.MoveAsset(src, dst);
if (string.IsNullOrEmpty(error))
{
    Debug.Log($"成功: {src} → {dst}");
}
else
{
    Debug.LogError($"重命名失败: {error}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

// 验证
string[] subs = AssetDatabase.GetSubFolders(dst);
Debug.Log($"SkillAsset 子文件夹: {subs.Length} 个");
foreach (var s in subs) Debug.Log($"  - {s}");

