using UnityEditor;
using UnityEngine;

Debug.Log("=== 引用完整性验证 ===");

// 1. 确认 SkillData 资产的 skillEffect 引用完好
string[] skillDataPaths = AssetDatabase.FindAssets("t:SkillData", new[] { "Assets/Resources/Skills/Data" });
foreach (var guid in skillDataPaths)
{
    string path = AssetDatabase.GUIDToAssetPath(guid);
    var sd = AssetDatabase.LoadAssetAtPath<SkillData>(path);
    if (sd == null) continue;
    bool effectOk = sd.skillEffect != null;
    bool iconOk = true;
    if (sd.skillId == "bacteriophage" || sd.skillId == "erode" || sd.skillId == "streptomyces")
        iconOk = sd.icon != null;
    Debug.Log($"  {sd.skillId}: effect={(effectOk ? "OK" : "BROKEN")} icon={(iconOk ? "OK" : "MISSING")}");
}

// 2. 确认 SkillAsset 子文件夹中的 prefab 可加载
string[] prefabGuids = AssetDatabase.FindAssets("t:Prefab", new[] { "Assets/Prefabs/SkillAsset" });
Debug.Log($"SkillAsset 下 prefab 数量: {prefabGuids.Length}");
foreach (var guid in prefabGuids)
{
    string path = AssetDatabase.GUIDToAssetPath(guid);
    Debug.Log($"  - {path}");
}

// 3. 检查旧路径是否不存在
bool oldExists = AssetDatabase.LoadAssetAtPath<Object>("Assets/Prefabs/Projectiles") != null;
Debug.Log($"旧路径 Assets/Prefabs/Projectiles 存在: {oldExists}");

// 4. 检查场景/预制体引用是否受影响（通过 GUID 验证 Bullet.prefab 等）
var bullet = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/SkillAsset/Bullet.prefab");
