using UnityEditor;
using UnityEngine;

// ── 1. 创建 AxonBlock 子文件夹 ──
string axonDir = "Assets/Prefabs/SkillAsset/AxonBlock";
if (!AssetDatabase.IsValidFolder(axonDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "AxonBlock");
Debug.Log($"确认文件夹: {axonDir}");

// ── 2. 移动 AxonBlock 技能资产到 SkillAsset/AxonBlock/ ──
var moves = new (string src, string dst)[]
{
    ("Assets/Materials/AxonBlockWave.mat",     axonDir + "/AxonBlockWave.mat"),
    ("Assets/Materials/AxonBlockOverlay.mat",  axonDir + "/AxonBlockOverlay.mat"),
    ("Assets/Shaders/DiffusionWave.shader",    axonDir + "/DiffusionWave.shader"),
    ("Assets/Shaders/WaveOverlay.shader",      axonDir + "/WaveOverlay.shader"),
};

foreach (var m in moves)
{
    if (AssetDatabase.LoadAssetAtPath<Object>(m.src) == null)
    {
        Debug.Log($"跳过（不存在）: {m.src}");
        continue;
    }
    string err = AssetDatabase.MoveAsset(m.src, m.dst);
    Debug.Log(string.IsNullOrEmpty(err)
        ? $"移动: {m.src} → {m.dst}"
        : $"失败: {m.src} → {m.dst} | {err}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

// ── 3. 验证结果 ──
Debug.Log("\n=== SkillAsset 目录结构 ===");
string[] subs = AssetDatabase.GetSubFolders("Assets/Prefabs/SkillAsset");
foreach (var s in subs)
{
    Debug.Log($"[DIR] {s}");
    string[] assets = System.IO.Directory.GetFiles(s.Replace("Assets/", ""), "*.*", System.IO.SearchOption.TopDirectoryOnly);
    foreach (var a in assets)
    {
        if (a.EndsWith(".meta")) continue;
        Debug.Log($"      {System.IO.Path.GetFileName(a)}");
    }
}

