using UnityEditor;
using UnityEngine;

string axonDir = "Assets/Resources/Skills/Data/AxonBlock";
string skillAssetDir = "Assets/Prefabs/SkillAsset/AxonBlock";

// ── 1. 备份材质（复制材质，保持 shader 不变）──
string circleWaveMat = skillAssetDir + "/AxonBlockCircleWave.mat";
string circleOverlayMat = skillAssetDir + "/AxonBlockCircleOverlay.mat";

AssetDatabase.CopyAsset(skillAssetDir + "/AxonBlockWave.mat", circleWaveMat);
AssetDatabase.CopyAsset(skillAssetDir + "/AxonBlockOverlay.mat", circleOverlayMat);
Debug.Log("材质备份: AxonBlockCircleWave.mat / AxonBlockCircleOverlay.mat");

// ── 2. 备份 Effect SO（圆形波配置）──
string circleEffectPath = axonDir + "/AxonBlockCircleEffect.asset";
AssetDatabase.CopyAsset(axonDir + "/AxonBlockEffect.asset", circleEffectPath);
Debug.Log("Effect 备份: AxonBlockCircleEffect.asset");

// ── 3. 备份 Effect 的材质引用指向备份材质（使其完全独立）──
var circleEffect = AssetDatabase.LoadAssetAtPath<WaveSkillEffect>(circleEffectPath);
if (circleEffect != null)
{
    var so = new SerializedObject(circleEffect);
    so.FindProperty("_waveMaterial").objectReferenceValue =
        AssetDatabase.LoadAssetAtPath<Material>(circleWaveMat);
    so.FindProperty("_overlayMaterial").objectReferenceValue =
        AssetDatabase.LoadAssetAtPath<Material>(circleOverlayMat);
    so.ApplyModifiedProperties();
    EditorUtility.SetDirty(circleEffect);
    Debug.Log("备份 Effect 材质引用已指向备份材质");
}

AssetDatabase.SaveAssets();
Debug.Log("=== 圆形波效果备份完成 ===");

