using UnityEditor;
using UnityEngine;

string dir = "Assets/Prefabs/SkillAsset/AxonBlock";

// ── 1. 降低波速，让扩散更可见 ──
string effectPath = "Assets/Resources/Skills/Data/AxonBlock/AxonBlockEffect.asset";
var effect = AssetDatabase.LoadAssetAtPath<WaveSkillEffect>(effectPath);
var so = new SerializedObject(effect);
so.FindProperty("_waveSpeed").floatValue = 12f;   // 25→12，扩散时长 0.4s→0.83s
so.FindProperty("_maxRadius").floatValue = 10f;
so.FindProperty("_spreadAngle").floatValue = 360f;
so.FindProperty("_freezeDuration").floatValue = 2f;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effect);
Debug.Log("waveSpeed → 12");

// ── 2. 增强波材质：更亮、更宽的环 ──
var waveMat = AssetDatabase.LoadAssetAtPath<Material>(dir + "/AxonBlockWave.mat");
if (waveMat != null)
{
    // 环宽 0.8→1.2，主色更亮，内色更亮
    waveMat.SetFloat("_RingWidth", 1.2f);
    waveMat.SetFloat("_Distortion", 0.12f);
    waveMat.SetColor("_Color", new Color(0.25f, 0.9f, 1.0f, 1.0f));
    waveMat.SetColor("_ColorInner", new Color(0.7f, 1.0f, 1.0f, 0.8f));
    EditorUtility.SetDirty(waveMat);
    Debug.Log("波材质增强：RingWidth=1.2，颜色更亮");
}

// ── 3. 增强 overlay 材质（扭曲更明显）──
var overlayMat = AssetDatabase.LoadAssetAtPath<Material>(dir + "/AxonBlockOverlay.mat");
if (overlayMat != null)
{
    overlayMat.SetFloat("_Distortion", 0.8f);
    overlayMat.SetColor("_Tint", new Color(0.2f, 0.45f, 0.7f, 0.25f));
    EditorUtility.SetDirty(overlayMat);
    Debug.Log("overlay 材质增强：Distortion=0.8");
}

AssetDatabase.SaveAssets();
Debug.Log("=== 参数调整完成 ===");

