using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "axon_block");

    // 释放技能
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已释放圆形波");

    // 等 0.45 秒（扩散中段），此时波环明显、扭曲脉冲在峰值附近
    yield return new WaitForSeconds(0.45f);

    var cam = Camera.main;
    // 使用截图管理器
    UnityTcp.Editor.Tools.ManageScreenshot.BeginCapture(1f);
    yield return new WaitForSeconds(0.05f);
    string path = UnityTcp.Editor.Tools.ManageScreenshot.EndCaptureToGif(
        System.IO.Path.Combine(Application.dataPath, "../screenshots/AxonBlockWaveTest.png"), 1, 128);

    Debug.Log($"截图路径: {path}");

    // 检查 WaveRuntime 是否创建
    var rt = Object.FindObjectOfType<WaveRuntime>();
    Debug.Log($"WaveRuntime 存在: {rt != null}, IsActive: {rt?.IsActive}");
}

return Run();

