using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "axon_block");

    // 玩家传送到敌群附近
    player.transform.position = new Vector3(0, 0, 0);

    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("释放技能");

    // 冻结期内检查（0.5s，波扩散中且冻结中）
    yield return new WaitForSeconds(0.5f);

    var enemies = Object.FindObjectsOfType<EnemyCore>();
    foreach (var e in enemies)
    {
        Debug.Log($"敌人 {e.name}: Movement.enabled={e.Movement?.enabled}, StateMachine={e.StateMachine?.enabled}");
        var sr = e.GetComponentInChildren<SpriteRenderer>();
        if (sr != null) Debug.Log($"  颜色: {sr.color}");
    }

    var rt = Object.FindObjectOfType<WaveRuntime>();
    Debug.Log($"WaveRuntime IsActive: {rt?.IsActive}");
}

return Run();

