using UnityEngine;

/// <summary>
/// 腐蚀性洪流技能效果：向前方呈扇形持续喷射腐蚀性洪流。
/// 期间施法者无法移动，仅可被喷射后坐力推动（朝向与喷射方向相反）。
/// 参考《以撒的结合》撒旦头/硫磺火的持续喷射形态。
/// 泛用类：持续时间、射程、扇形角度、每秒伤害、后坐力均可配置。
/// 右键 -> Create -> Game -> Skill Effect -> Corrosive Torrent
/// </summary>
[CreateAssetMenu(fileName = "TorrentEffect", menuName = "Game/Skill Effect/Corrosive Torrent")]
public class TorrentSkillEffect : SkillEffectBase
{
    [Header("喷射配置")]
    [Tooltip("喷射持续时间（秒）")]
    [SerializeField] private float _duration = 20f;
    [Tooltip("喷射射程")]
    [SerializeField] private float _range = 8f;
    [Tooltip("扇形扩散角度（度）")]
    [SerializeField] private float _spreadAngle = 60f;
    [Tooltip("每秒伤害")]
    [SerializeField] private float _damagePerSecond = 20f;
    [Tooltip("伤害结算间隔（秒），越小越平滑")]
    [SerializeField] private float _damageInterval = 0.2f;

    [Header("后坐力")]
    [Tooltip("后坐力移动速度（朝向与喷射方向相反）")]
    [SerializeField] private float _knockbackSpeed = 2.5f;

    [Header("视觉材质")]
    [Tooltip("洪流材质（使用 CorrosiveTorrent shader）")]
    [SerializeField] private Material _torrentMaterial;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        // 已有同类效果在进行中则不重复触发
        var existing = FindObjectOfType<TorrentRuntime>();
        if (existing != null && existing.IsActive) return;

        var go = new GameObject("CorrosiveTorrent");
        var runtime = go.AddComponent<TorrentRuntime>();

        runtime.Initialize(
            caster, direction,
            _duration, _range, _spreadAngle,
            _damagePerSecond, _damageInterval,
            _knockbackSpeed,
            _torrentMaterial
        );
    }
}

using UnityEngine;

/// <summary>
/// 腐蚀性洪流运行时组件：向前方扇形持续喷射腐蚀洪流，对范围内敌人持续造成伤害。
/// 期间施法者无法移动（InputLocked），仅可被喷射后坐力推动（朝向与喷射方向相反）。
/// 玩家阵营时喷射方向实时跟随鼠标。
/// </summary>
public class TorrentRuntime : MonoBehaviour
{
    // ── 配置（由 Initialize 设置）──
    private ISkillCaster _caster;
    private Vector2 _castDirection;
    private float _duration;
    private float _range;
    private float _spreadAngleDeg;
    private float _damagePerSecond;
    private float _knockbackSpeed;
    private float _damageInterval;
    private Material _torrentMaterial;
    private Projectile.OwnerType _ownerType;

    // ── 施法者引用 ──
    private GameObject _casterGO;
    private Rigidbody2D _casterRb;
    private PlayerController _playerController;

    // ── 运行时状态 ──
    private float _timer;
    private bool _isActive;
    private float _nextDamageTime;

    // ── 视觉 ──
    private GameObject _visualGO;
    private SpriteRenderer _visualRenderer;
    private Material _visualMatInstance;

    /// <summary>是否正在喷射中</summary>
    public bool IsActive => _isActive;

    /// <summary>
    /// 初始化腐蚀洪流。
    /// </summary>
    public void Initialize(ISkillCaster caster, Vector2 direction,
                           float duration, float range, float spreadAngleDeg,
                           float damagePerSecond, float damageInterval,
                           float knockbackSpeed,
                           Material torrentMaterial)
    {
        _caster = caster;
        _castDirection = direction.sqrMagnitude > 0.0001f ? direction.normalized : Vector2.right;
        _duration = duration;
        _range = range;
        _spreadAngleDeg = spreadAngleDeg;
        _damagePerSecond = damagePerSecond;
        _damageInterval = Mathf.Max(damageInterval, 0.05f);
        _knockbackSpeed = knockbackSpeed;
        _torrentMaterial = torrentMaterial;
        _ownerType = caster.GetOwnerType();

        _timer = duration;
        _isActive = true;
        _nextDamageTime = 0f;

        _casterGO = caster.CasterTransform.gameObject;
        _casterRb = _casterGO.GetComponent<Rigidbody2D>();
        _playerController = _casterGO.GetComponent<PlayerController>();

        // 锁定施法者移动（仅玩家有 PlayerController）
        if (_playerController != null)
            _playerController.InputLocked = true;
        if (_casterRb != null)
            _casterRb.velocity = Vector2.zero;

        CreateVisual();
    }

    // ──────────────────────────────────────────────
    //  每帧更新
    // ──────────────────────────────────────────────

    private void Update()
    {
        if (!_isActive) return;

        _timer -= Time.deltaTime;

        // 玩家阵营：方向实时跟随鼠标；敌人阵营保持朝向玩家
        UpdateDirection();

        // 持续伤害（按 tick 间隔结算）
        if (Time.time >= _nextDamageTime)
        {
            _nextDamageTime = Time.time + _damageInterval;
            ApplyDamage();
        }

        // 后坐力推动（持续施加，撞墙被碰撞系统阻挡）
        ApplyKnockback();

        // 视觉跟随 + 旋转
        UpdateVisual();

        if (_timer <= 0f)
            EndEffect();
    }

    // ──────────────────────────────────────────────
    //  方向
    // ──────────────────────────────────────────────

    private void UpdateDirection()
    {
        if (_ownerType == Projectile.OwnerType.Player && Camera.main != null)
        {
            Vector3 mouseWorld = Camera.main.ScreenToWorldPoint(Input.mousePosition);
            mouseWorld.z = 0f;
            Vector2 toMouse = (Vector2)(mouseWorld - _casterGO.transform.position);
            if (toMouse.sqrMagnitude > 0.0001f)
                _castDirection = toMouse.normalized;
        }
        else if (_ownerType == Projectile.OwnerType.Enemy)
        {
            // 敌人阵营：朝向目标方向（GetTargetDirection 已实现朝向玩家）
            Vector2 targetDir = _caster.GetTargetDirection();
            if (targetDir.sqrMagnitude > 0.0001f)
                _castDirection = targetDir.normalized;
        }
    }

    // ──────────────────────────────────────────────
    //  伤害
    // ──────────────────────────────────────────────

    private void ApplyDamage()
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(_casterGO.transform.position, _range);
        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        float tickDamage = _damagePerSecond * _damageInterval;
        float halfAngle = _spreadAngleDeg * 0.5f;
        Vector2 origin = _casterGO.transform.position;

        foreach (var hit in hits)
        {
            if (hit == null) continue;
            if (!hit.CompareTag(targetTag)) continue;

            Vector2 toTarget = (Vector2)hit.transform.position - origin;
            float dist = toTarget.magnitude;
            if (dist > _range || dist < 0.01f) continue;

            // 扇形角度过滤
            if (Vector2.Angle(toTarget, _castDirection) > halfAngle) continue;

            if (hit.TryGetComponent<IDamageable>(out var d))
                d.TakeDamage(tickDamage);
        }
    }

    // ──────────────────────────────────────────────
    //  后坐力
    // ──────────────────────────────────────────────

    private void ApplyKnockback()
    {
        if (_casterRb == null) return;

        // 后坐力方向 = 喷射方向的反方向（远离鼠标）
        Vector2 knockDir = -_castDirection;
        _casterRb.velocity = knockDir * _knockbackSpeed;
    }

    // ──────────────────────────────────────────────
    //  视觉
    // ──────────────────────────────────────────────

    private void CreateVisual()
    {
        _visualGO = new GameObject("TorrentVisual");
        _visualGO.transform.SetParent(transform);

        _visualRenderer = _visualGO.AddComponent<SpriteRenderer>();
        if (_torrentMaterial != null)
        {
            _visualMatInstance = new Material(_torrentMaterial);
            _visualRenderer.material = _visualMatInstance;
        }
        _visualRenderer.sprite = CreateWhiteSprite();
        _visualRenderer.sortingOrder = 50;

        float scale = _range * 2f;
        _visualGO.transform.localScale = new Vector3(scale, scale, 1f);

        UpdateVisual();
    }

    private void UpdateVisual()
    {
        if (_visualGO == null) return;

        // 位置跟随施法者
        _visualGO.transform.position = _casterGO.transform.position;

        // 旋转朝向喷射方向
        float angle = Mathf.Atan2(_castDirection.y, _castDirection.x) * Mathf.Rad2Deg;
        _visualGO.transform.rotation = Quaternion.Euler(0f, 0f, angle);

        // shader 参数
        if (_visualMatInstance != null)
        {
            _visualMatInstance.SetFloat("_Range", _range);
            _visualMatInstance.SetFloat("_SpreadAngle", _spreadAngleDeg * Mathf.Deg2Rad);
        }
    }

    // ──────────────────────────────────────────────
    //  结束 / 清理
    // ──────────────────────────────────────────────

    private void EndEffect()
    {
        if (!_isActive) return;
        _isActive = false;

        // 解锁移动
        if (_playerController != null)
            _playerController.InputLocked = false;
        if (_casterRb != null)
            _casterRb.velocity = Vector2.zero;

        Destroy(gameObject);
    }

    private void OnDestroy()
    {
        // 确保解锁（防止意外销毁时施法者卡死）
        if (_isActive)
        {
            if (_playerController != null)
                _playerController.InputLocked = false;
            if (_casterRb != null)
                _casterRb.velocity = Vector2.zero;
        }
    }

    /// <summary>生成纯白 1x1 sprite（PPU=1），scale 直接等于世界尺寸</summary>
    private static Sprite CreateWhiteSprite()
    {
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
    }
}

Shader "Custom/CorrosiveTorrent"
{
    Properties
    {
        _Range ("Range", Float) = 8
        _SpreadAngle ("Spread Angle", Range(0, 6.2832)) = 1.0472
        _Color ("Color", Color) = (0.3, 1.0, 0.5, 0.8)
        _ColorDeep ("Deep Color", Color) = (0.1, 0.6, 0.35, 0.9)
        _FlowSpeed ("Flow Speed", Float) = 3
        _NoiseScale ("Noise Scale", Float) = 6
        _Distortion ("Distortion", Float) = 0.2
        _Opacity ("Opacity", Range(0,1)) = 0.75
    }
    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "Queue" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
        }
        Blend SrcAlpha OneMinusSrcAlpha
        ZWrite Off
        Cull Off

        Pass
        {
            Name "Forward"
            Tags { "LightMode" = "UniversalForward" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma multi_compile_fog

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float _Range;
                float _SpreadAngle;
                float4 _Color;
                float4 _ColorDeep;
                float _FlowSpeed;
                float _NoiseScale;
                float _Distortion;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                float fogFactor : TEXCOORD1;
            };

            float hash21(float2 p)
            {
                p = frac(p * float2(123.34, 456.21));
                p += dot(p, p + 45.32);
                return frac(p.x * p.y);
            }

            float noise2D(float2 p)
            {
                float2 i = floor(p);
                float2 f = frac(p);
                f = f * f * (3.0 - 2.0 * f);
                float a = hash21(i);
                float b = hash21(i + float2(1.0, 0.0));
                float c = hash21(i + float2(0.0, 1.0));
                float d = hash21(i + float2(1.0, 1.0));
                return lerp(lerp(a, b, f.x), lerp(c, d, f.x), f.y);
            }

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                OUT.fogFactor = ComputeFogFactor(IN.positionOS.z);
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                // 局部坐标：uv 0~1 → 中心化后 ×2 映射到 [-R, R]
                float2 centered = IN.uv - 0.5;
                float distNorm = length(centered) * 2.0;   // 0~1
                float worldDist = distNorm * _Range;

                // 扇形角度（0 度 = +x 轴，视觉 GO 已旋转朝向喷射方向）
                float angle = atan2(centered.y, centered.x);
                float halfAngle = _SpreadAngle * 0.5;

                // 扇形遮罩（边缘平滑）
                float angMask = 1.0 - smoothstep(halfAngle - 0.15, halfAngle, abs(angle));

                // 距离渐变：近处口部淡、中段浓、远处淡
                float mouthFade = smoothstep(0.0, _Range * 0.1, worldDist);
                float distFade = 1.0 - smoothstep(_Range * 0.6, _Range, worldDist);
                float distMask = mouthFade * distFade;

                // ── 流动动画：沿径向向外流动的噪声 ──
                float t = _Time.y * _FlowSpeed;

                // 噪声坐标：径向拉伸（r 越大越密），随时间向 +x（喷射方向）流动
                float2 flowUv = centered * _NoiseScale;
                // 径向流动：沿喷射轴流动 + 横向扰动
                float2 dir = float2(1.0, 0.0);
                float2 flowPos = flowUv - dir * t * 0.8 + float2(noise2D(flowUv + t) - 0.5, 0) * _Distortion;

                float n1 = noise2D(flowPos);
                float n2 = noise2D(flowPos * 1.7 + 3.7);

                // 液流强度：中心浓、边缘淡 + 噪声流动
                float flowStrength = angMask * distMask * (0.55 + 0.45 * n1);

                // 深色内核 + 亮色外层
                float coreMask = smoothstep(0.6, 0.0, abs(angle) / max(halfAngle, 0.01));
                float4 col = lerp(_ColorDeep, _Color, 0.5 + 0.5 * n2);
                col.rgb *= 0.8 + 0.4 * n1;

                col.a = flowStrength * _Opacity * (0.7 + 0.3 * coreMask);

                if (col.a < 0.01) discard;

                col.rgb = MixFog(col.rgb, IN.fogFactor);
                return col;
            }
