using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/ThrombolyticInfusion";
string dataDir = "Assets/Resources/Skills/Data/ThrombolyticInfusion";

// ── 1. 确保文件夹存在 ──
if (!AssetDatabase.IsValidFolder(skillDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "ThrombolyticInfusion");
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "ThrombolyticInfusion");

// ── 2. 创建材质 ──
Shader shader = Shader.Find("Custom/CorrosiveTorrent");
if (shader == null) { Debug.LogError("CorrosiveTorrent shader 未找到!"); return; }

string matPath = skillDir + "/CorrosiveTorrent.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetFloat("_Range", 8f);
mat.SetFloat("_SpreadAngle", Mathf.Deg2Rad * 60f);
mat.SetColor("_Color", new Color(0.3f, 1.0f, 0.5f, 0.8f));
mat.SetColor("_ColorDeep", new Color(0.1f, 0.6f, 0.35f, 0.9f));
mat.SetFloat("_FlowSpeed", 3f);
mat.SetFloat("_NoiseScale", 6f);
mat.SetFloat("_Distortion", 0.2f);
mat.SetFloat("_Opacity", 0.75f);
EditorUtility.SetDirty(mat);
Debug.Log("材质: " + matPath);

// ── 3. 创建 Effect SO ──
string effectPath = dataDir + "/TorrentEffect.asset";
TorrentSkillEffect effect = AssetDatabase.LoadAssetAtPath<TorrentSkillEffect>(effectPath);
if (effect == null)
{
    effect = ScriptableObject.CreateInstance<TorrentSkillEffect>();
    AssetDatabase.CreateAsset(effect, effectPath);
}
var so = new SerializedObject(effect);
so.FindProperty("_duration").floatValue = 20f;
so.FindProperty("_range").floatValue = 8f;
so.FindProperty("_spreadAngle").floatValue = 60f;
so.FindProperty("_damagePerSecond").floatValue = 20f;
so.FindProperty("_damageInterval").floatValue = 0.2f;
so.FindProperty("_knockbackSpeed").floatValue = 2.5f;
so.FindProperty("_torrentMaterial").objectReferenceValue = mat;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effect);
Debug.Log("Effect: " + effectPath);

// ── 4. 创建 SkillData ──
string dataPath = dataDir + "/ThrombolyticInfusion.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "thrombolytic_infusion";
sd.skillName = "溶栓灌注";
sd.description = "向前方喷射大范围腐蚀性洪流，持续20秒，对范围内敌人持续造成伤害。期间无法移动，仅可被喷射后坐力推动（朝向与鼠标相反）。";
sd.cooldown = 30f;
sd.castRange = 8f;
sd.damageMultiplier = 1f;
sd.maxLevel = 3;
sd.skillEffect = effect;
sd.icon = null;
EditorUtility.SetDirty(sd);
Debug.Log("SkillData: " + dataPath);

// ── 5. 注册 SkillLibrary ──
SkillLibrary lib = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
bool found = false;
foreach (var s in lib.AllSkills)
{
    if (s != null && s.skillId == "thrombolytic_infusion") { found = true; break; }
}
if (!found)
{
    var field = typeof(SkillLibrary).GetField("_allSkills",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var list = field.GetValue(lib) as System.Collections.Generic.List<SkillData>;
    if (list != null)
    {
        list.Add(sd);
        Debug.Log("已注册到 SkillLibrary");
    }
    EditorUtility.SetDirty(lib);
}
else Debug.Log("已在 SkillLibrary 中");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 溶栓灌注资产创建完成 ===");

