using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    if (player == null) { Debug.LogError("未找到玩家!"); yield break; }
    var skillMgr = player.GetComponent<PlayerSkillManager>();

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "thrombolytic_infusion");
    if (sd == null) { Debug.LogError("thrombolytic_infusion 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    // 玩家放在敌人左侧，让喷射方向朝向敌人（右侧）
    player.transform.position = new Vector3(-2, 0, 0);

    // 释放技能（方向朝右）
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已释放溶栓灌注");

    // 检查 TorrentRuntime 状态
    yield return new WaitForSeconds(0.3f);
    var rt = Object.FindObjectOfType<TorrentRuntime>();
    var pc = player.GetComponent<PlayerController>();
    Debug.Log($"TorrentRuntime 存在: {rt != null}, IsActive: {rt?.IsActive}");
    Debug.Log($"玩家 InputLocked: {pc?.InputLocked}");

    // 后坐力方向 = 鼠标反方向。模拟鼠标在右 → 后坐力向左
    Vector3 mouseWorld = Camera.main.ScreenToWorldPoint(Input.mousePosition);
    Debug.Log($"鼠标世界位置: {mouseWorld}, 玩家位置: {player.transform.position}");

    // 等 0.5 秒观察玩家是否被后坐力推动
    Vector3 startPos = player.transform.position;
    yield return new WaitForSeconds(0.5f);
    Debug.Log($"后坐力测试: 起始 {startPos}, 当前 {player.transform.position}, 位移 {(player.transform.position - startPos).magnitude}");

    // 检查敌人是否受伤
    var enemies = Object.FindObjectsOfType<EnemyCore>();
    foreach (var e in enemies)
    {
        Debug.Log($"敌人 {e.name} @ {e.transform.position}, Health: {e.Health?.CurrentHealth}");
    }
}

return Run();

