                float2 detailUv = centered * (_NoiseScale * 2.2) - float2(t * 1.4, 0.0);
                float detailN = fbm(detailUv + angle * 0.5);
                float mottle = pow(abs(detailN), 1.6);

                float streamUv = angle * 10.0 - worldDist * 2.0 + t * 2.5;
                float streamRaw = sin(streamUv) * 0.5 + 0.5;
                float stream = smoothstep(0.35, 0.75, streamRaw);

                float2 bubbleUv = centered * 26.0 - float2(t * 1.2, t * 0.6);
                float bubbleCell = hash21(floor(bubbleUv) + 7.7);
                float bubble = smoothstep(0.76, 0.86, bubbleCell);
                float2 bubbleFrac = frac(bubbleUv) - 0.5;
                float bubbleDist = length(bubbleFrac);
                bubble *= 1.0 - smoothstep(0.1, 0.26, bubbleDist);

                float2 dropUv = centered * 40.0 - float2(t * 2.2, t * 0.9);
                float dropCell = hash21(floor(dropUv) + 3.1);
                float drop = smoothstep(0.88, 0.94, dropCell);
                float2 dropFrac = frac(dropUv) - 0.5;
                drop *= 1.0 - smoothstep(0.06, 0.18, length(dropFrac));

                float bodyNoise = fbm(flowUv + float2(-t * 0.9, 0.25 * sin(t + angle * 3.0)));
                float liquidBody = angMask * distMask
                    * (0.25 + 0.75 * bodyNoise)
                    * (0.4 + 0.6 * stream)
                    * (0.55 + 0.45 * mottle * _Detail);

                liquidBody += bubble * 0.5 * distMask * angMask;
                liquidBody += drop * 0.6 * distMask * angMask;

                float edgeFactor = 1.0 - smoothstep(halfAngle * 0.5, halfAngle, abs(angle));
                float4 col = lerp(_ColorDeep, _Color, 0.3 + 0.7 * edgeFactor + 0.3 * turb2);
                col.rgb *= 0.65 + 0.7 * mottle * _Detail;
                col.rgb += float3(0.15, 0.25, 0.05) * drop * 1.2;

                col.a = liquidBody * _Opacity;

                if (col.a < 0.01) discard;

                return col;
            }
            ENDHLSL
        }
    }
    FallBack "Sprites/Default"
}

