            #pragma fragment frag

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float _Range;
                float _SpreadAngle;
                float4 _Color;
                float4 _ColorDeep;
                float _FlowSpeed;
                float _NoiseScale;
                float _Turbulence;
                float _Detail;
                float _Opacity;
