    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "thrombolytic_infusion");

    var old = Object.FindObjectsOfType<TorrentRuntime>();
    foreach (var o in old) Object.Destroy(o.gameObject);
    yield return null;

    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);

    // 等粒子生成
    yield return new WaitForSeconds(0.5f);

    var psGO = GameObject.Find("TorrentSpray");
