args.script:
using UnityEditor;
using UnityEngine;

// ── 1. 删除 SprayAdditive.shader（光效专用）──
string sprayPath = "Assets/Prefabs/SkillAsset/ThrombolyticInfusion/SprayAdditive.shader";
if (AssetDatabase.LoadAssetAtPath<Shader>(sprayPath) != null)
{
    AssetDatabase.DeleteAsset(sprayPath);
    Debug.Log("已删除 SprayAdditive.shader");
}

// ── 2. 清理材质 Glow 参数（shader 已回退，多余属性会自动忽略）──
string matPath = "Assets/Prefabs/SkillAsset/ThrombolyticInfusion/CorrosiveTorrent.mat";
var mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat != null)
{
    // 保留之前调浓的底色（用户满意），清掉 Glow
    if (mat.HasProperty("_GlowColor"))
        mat.SetColor("_GlowColor", Color.clear);
    if (mat.HasProperty("_GlowIntensity"))
        mat.SetFloat("_GlowIntensity", 0f);
    EditorUtility.SetDirty(mat);
    Debug.Log("材质 Glow 参数已清零，shader 回退为标准透明混合");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 光效回退完成 ===");

