string oldColor = "new Color(0.25f, 1.0f, 0.45f, 0.9f),\n            new Color(0.05f, 0.5f, 0.3f, 0.7f)";
string newColor = "new Color(0.15f, 0.8f, 0.35f, 0.9f),\n            new Color(0.02f, 0.35f, 0.15f, 0.7f)";
if (src.Contains(oldColor))
{
    src = src.Replace(oldColor, newColor);
