        _BubbleSpeed ("Bubble Speed", Float) = 2
        _BubbleDensity ("Bubble Density", Float) = 12
        _BubbleStrength ("Bubble Strength", Range(0,1)) = 0.5
        _Opacity ("Opacity", Range(0,1)) = 0.85
    }
    SubShader
    {
