args.script:
using UnityEditor;
using UnityEngine;

string dir = "Assets/Prefabs/SkillAsset/HypertonicLysate";
if (!AssetDatabase.IsValidFolder(dir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "HypertonicLysate");

// ── 1. 材质 ──
Shader shader = Shader.Find("Custom/GroundSolution");
if (shader == null) { Debug.LogError("GroundSolution shader 未找到!"); return; }

string matPath = dir + "/GroundSolution.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetFloat("_Radius", 2f);
mat.SetColor("_Color", new Color(0.55f, 0.25f, 0.7f, 0.85f));       // 紫色裂解液
mat.SetColor("_ColorEdge", new Color(0.75f, 0.45f, 0.95f, 0.5f));
mat.SetFloat("_BubbleSpeed", 2f);
mat.SetFloat("_BubbleDensity", 12f);
mat.SetFloat("_BubbleStrength", 0.5f);
mat.SetFloat("_Opacity", 0.85f);
EditorUtility.SetDirty(mat);
Debug.Log("材质: " + matPath);

// ── 2. 溶液预制体 ──
string prefabPath = dir + "/HypertonicLysate.prefab";
GameObject existing = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
if (existing == null)
{
    // 创建临时对象构建预制体
    var go = new GameObject("HypertonicLysate");

    // SpriteRenderer + 材质
    var sr = go.AddComponent<SpriteRenderer>();
    sr.material = mat;
    sr.sortingOrder = 20;

    // 1x1 白色 sprite（PPU=1，scale 即直径）
    var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
    tex.SetPixel(0, 0, Color.white);
    tex.Apply();
    sr.sprite = Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);

    // scale = 直径 = radius * 2 = 4
    go.transform.localScale = new Vector3(4f, 4f, 1f);

    // Collider2D（匹配伤害范围；用 CircleCollider 便于敌人踩踏触发）
    var col = go.AddComponent<CircleCollider2D>();
    col.radius = 0.5f;
    col.isTrigger = true;

    // Projectile（speed=0 原地；生命周期由 GroundSolutionZone 接管）
    var proj = go.AddComponent<Projectile>();

    // 地面溶液持续伤害组件
    var zone = go.AddComponent<GroundSolutionZone>();

    // 保存预制体
    prefabPath = PrefabUtility.SaveAsPrefabAsset(go, prefabPath);
    Debug.Log("预制体: " + prefabPath);

    Object.DestroyImmediate(go);
}
else
{
    Debug.Log("预制体已存在: " + prefabPath);
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 溶液预制体创建完成 ===");

