if (effect == null)
{
    effect = ScriptableObject.CreateInstance<ProjectileSkillEffect>();
    AssetDatabase.CreateAsset(effect, effectPath);
}
effect.projectilePrefab =
    AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/SkillAsset/HypertonicLysate/HypertonicLysate.prefab");
effect.speed = 0f;        // 原地释放，不移动
effect.count = 1;
effect.spreadAngle = 0f;
EditorUtility.SetDirty(effect);
Debug.Log("Effect: " + effectPath + " (speed=0 原地释放)");

// ── 2. SkillData ──
string dataPath = dataDir + "/HypertonicLysate.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "hypertonic_lysate";
sd.skillName = "高渗裂解剂";
sd.description = "在原地生成一滩高渗裂解溶液，敌人踩在上面持续受到伤害，持续10秒。";
