using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length == 0) { Debug.LogError("场景无敌人!"); yield break; }
    var enemy = enemies[0];
    var enemyStats = enemy.Health;

    // 敌人放在玩家前方（溶液会生成在玩家脚下，敌人走过去踩）
    enemy.transform.position = new Vector3(3, 0, 0);
    Debug.Log($"敌人 @ {enemy.transform.position}, 初始生命: {enemyStats.CurrentHealth}");

    // 玩家施放高渗裂解剂（原地生成溶液）
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "hypertonic_lysate");
    if (sd == null) { Debug.LogError("hypertonic_lysate 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    // 玩家脚下生成溶液
    player.transform.position = new Vector3(0, 0, 0);
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("玩家已施放高渗裂解剂（原地生成溶液）");

    // 检查溶液是否生成
    yield return new WaitForSeconds(0.3f);
    var zones = Object.FindObjectsOfType<GroundSolutionZone>();
    Debug.Log($"溶液区域数量: {zones.Length}");

    // 把敌人传送到溶液上，验证持续伤害
    if (zones.Length > 0)
    {
        enemy.transform.position = zones[0].transform.position;
        Debug.Log($"敌人已传送到溶液上 @ {enemy.transform.position}");
    }

    float before = enemyStats.CurrentHealth;
    yield return new WaitForSeconds(1.5f);
    float after = enemyStats.CurrentHealth;
    Debug.Log($"敌人生命: {before} → {after} (1.5s 受伤 {(before - after):F1}, 期望 ~22.5)");
}

return Run();

