using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 清场：销毁所有敌人和旧溶液，玩家单独测试
    foreach (var e in Object.FindObjectsOfType<EnemyCore>())
        Object.Destroy(e.gameObject);
    foreach (var z in Object.FindObjectsOfType<GroundSolutionZone>())
        Object.Destroy(z.gameObject);
    yield return new WaitForSeconds(0.5f);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "hypertonic_lysate");

    float before = player.GetComponent<PlayerStats>().CurrentHealth;
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log($"玩家施放溶液，当前生命: {before}");

    // 玩家站在自己的溶液上 2 秒
    yield return new WaitForSeconds(2f);
    float after = player.GetComponent<PlayerStats>().CurrentHealth;
    Debug.Log($"2s 后玩家生命: {after} (变化 {(after - before):F1})");
    Debug.Log(after < before ? "⚠️ 溶液误伤玩家！" : "✅ 溶液不伤自己（玩家不受影响）");
}

return Run();

