using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 把敌人移回场景（之前测试移到 (50,50)）
    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length == 0) { Debug.LogError("场景无敌人!"); yield break; }
    var enemy = enemies[0];

    // 玩家放敌人脚下，让敌人施放溶液在玩家脚下
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    enemy.transform.position = new Vector3(0, 2, 0);

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "hypertonic_lysate");

    // 敌人加载并施放高渗裂解剂
    enemy.SkillManager.LoadSkills(lib, "hypertonic_lysate");
    sd.skillEffect.Execute(enemy, Vector2.down, 1f, enemy.GetOwnerType());
    Debug.Log($"敌人已施放高渗裂解剂 (ownerType={enemy.GetOwnerType()})");

    // 检查溶液阵营
    yield return new WaitForSeconds(0.3f);
    var zones = Object.FindObjectsOfType<GroundSolutionZone>();
    Debug.Log($"溶液数量: {zones.Length}");

    // 玩家传送到溶液上（敌人施放的，应该打玩家）
    if (zones.Length > 0)
    {
        player.transform.position = zones[0].transform.position;
        Debug.Log($"玩家传送到溶液上 @ {player.transform.position}");
    }

    float before = player.GetComponent<PlayerStats>().CurrentHealth;
    yield return new WaitForSeconds(2f);
    float after = player.GetComponent<PlayerStats>().CurrentHealth;
    Debug.Log($"玩家生命: {before} → {after} (2s 受伤 {(before - after):F1}, 期望 ~30)");
    Debug.Log(after < before ? "✅ 敌人溶液正确伤害玩家" : "⚠️ 玩家未受伤");
}

return Run();

