using UnityEditor;
using UnityEngine;

string dir = "Assets/Resources/Skills/Data/HypertonicLysate";

// ── 1. DamageOverTimeBuff effect 资产 ──
string dotPath = dir + "/LysateDOTEffect.asset";
DamageOverTimeBuff dotEffect = AssetDatabase.LoadAssetAtPath<DamageOverTimeBuff>(dotPath);
if (dotEffect == null)
{
    dotEffect = ScriptableObject.CreateInstance<DamageOverTimeBuff>();
    AssetDatabase.CreateAsset(dotEffect, dotPath);
}
dotEffect.damagePerTick = 15f;
dotEffect.tickInterval = 1f;
EditorUtility.SetDirty(dotEffect);
Debug.Log("DOT effect: " + dotPath + " (15/tick, 1s interval)");

// ── 2. BuffData 资产 ──
string buffPath = dir + "/LysateDebuff.asset";
BuffData buffData = AssetDatabase.LoadAssetAtPath<BuffData>(buffPath);
if (buffData == null)
{
    buffData = ScriptableObject.CreateInstance<BuffData>();
    AssetDatabase.CreateAsset(buffData, buffPath);
}
buffData.buffId = "hypertonic_lysate_debuff";
buffData.buffName = "高渗裂解";
buffData.description = "高渗裂解液持续腐蚀目标，每秒造成15点伤害。在溶液圈内停留会刷新持续时间。";
buffData.buffType = BuffType.Debuff;
buffData.duration = 3f;                    // debuff 自身时长 3s
buffData.isPermanent = false;
buffData.stackable = false;                // 不可叠加
buffData.maxStacks = 1;
buffData.stackBehavior = StackBehavior.Refresh;   // 圈内停留 → 刷新时长
buffData.effect = dotEffect;
buffData.icon = null;
EditorUtility.SetDirty(buffData);
Debug.Log("BuffData: " + buffPath + " (duration=3s, Refresh)");

// ── 3. 绑定到溶液预制体 ──
string prefabPath = "Assets/Prefabs/SkillAsset/HypertonicLysate/HypertonicLysate.prefab";
var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
if (prefab != null)
{
    var zone = prefab.GetComponent<GroundSolutionZone>();
    var so = new SerializedObject(zone);
    so.FindProperty("_radius").floatValue = 2f;
    so.FindProperty("_duration").floatValue = 10f;
    so.FindProperty("_refreshInterval").floatValue = 0.25f;
    so.FindProperty("_debuffData").objectReferenceValue = buffData;
    so.ApplyModifiedProperties();
    EditorUtility.SetDirty(prefab);
    Debug.Log("预制体 GroundSolutionZone 已绑定 debuff: " + buffPath);
}
else Debug.LogError("溶液预制体未找到!");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== LysateDebuff 资产创建完成 ===");

