using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人移远（避免近战干扰）
    foreach (var e in Object.FindObjectsOfType<EnemyCore>())
        e.transform.position = new Vector3(50, 50, 0);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "hypertonic_lysate");

    // 施放溶液
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.5f);

    var zones = Object.FindObjectsOfType<GroundSolutionZone>();
    Debug.Log($"溶液数量: {zones.Length}");
    if (zones.Length == 0) { Debug.LogError("溶液未生成!"); yield break; }

    // 检查溶液渲染
    var sr = zones[0].GetComponent<SpriteRenderer>();
    Debug.Log($"溶液 sprite: {(sr.sprite != null ? sr.sprite.name : "NULL")}, 材质: {sr.sharedMaterial?.shader?.name}");

    // 敌人传送到溶液上
    var enemy = Object.FindObjectsOfType<EnemyCore>().First();
    enemy.transform.position = zones[0].transform.position;
    Debug.Log($"敌人踩上溶液 @ {enemy.transform.position}");

    // 等 1.5s 检查 debuff 和伤害
    yield return new WaitForSeconds(1.5f);
    var buffMgr = enemy.GetComponent<BuffManager>();
    Debug.Log($"敌人 BuffManager: {(buffMgr != null ? "有" : "无")}");
    if (buffMgr != null)
    {
        Debug.Log($"敌人有裂解debuff: {buffMgr.HasBuff("hypertonic_lysate_debuff")}");
        var buff = buffMgr.GetBuff("hypertonic_lysate_debuff");
        if (buff != null) Debug.Log($"debuff 剩余时长: {buff.RemainingDuration:F1}s, 堆叠: {buff.CurrentStacks}");
    }
    Debug.Log($"敌人生命: {enemy.Health.CurrentHealth}");
}

return Run();

