using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 重新施放（敌人已在圈内），截图验证溶液视觉
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(-3, 0, 0); // 玩家移开溶液位置

    UnityTcp.Editor.Tools.ManageScreenshot.BeginCapture(1f);
    yield return new WaitForSeconds(0.05f);
    string path = UnityTcp.Editor.Tools.ManageScreenshot.EndCaptureToGif(
        System.IO.Path.Combine(Application.dataPath, "../screenshots/LysateV2.png"), 1, 128);
    Debug.Log($"截图: {path}");

    // 刷新机制测试：敌人留在圈内，检查 debuff 是否持续存在
    var enemy = Object.FindObjectsOfType<EnemyCore>().First();
    var buffMgr = enemy.GetComponent<BuffManager>();

    float hpStart = enemy.Health.CurrentHealth;
    // 等 3.5s（> debuff 时长 3s）
    yield return new WaitForSeconds(3.5f);

    bool hasDebuff = buffMgr.HasBuff("hypertonic_lysate_debuff");
    var buff = buffMgr.GetBuff("hypertonic_lysate_debuff");
    float hpNow = enemy.Health.CurrentHealth;
    Debug.Log($"3.5s 后: debuff存在={hasDebuff}, 剩余时长={(buff != null ? buff.RemainingDuration.ToString("F1") : "N/A")}, 生命 {hpStart}→{hpNow}");
    Debug.Log(hasDebuff && hpNow < hpStart ? "✅ 圈内刷新机制生效（debuff 持续存在且持续伤害）" : "⚠️ 刷新机制异常");
}

return Run();

