using UnityEngine;

/// <summary>
/// 混乱状态：敌人随处乱走（随机方向漫步），不检测玩家、不攻击、不施放技能。
/// 由急性谵妄 debuff 施加，持续期间敌人完全失去攻击性。
/// </summary>
public class ConfusedState : EnemyStateBase
{
    private Vector2 _wanderDir;
    private float _changeTimer;
    private static readonly float ChangeInterval = 0.8f;   // 每隔多久换一次方向
    private static readonly float WanderDistance = 3f;      // 每次漫步的目标距离

    public ConfusedState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _changeTimer = 0f;
        _wanderDir = Random.insideUnitCircle.normalized;
        if (Core.Movement != null)
            Core.Movement.MoveSpeed = Core.config != null ? Core.config.patrolSpeed : 1f;
    }

    public override void Tick()
    {
        // 定时更换随机方向（随处乱走）
        _changeTimer += Time.deltaTime;
        if (_changeTimer >= ChangeInterval)
        {
            _changeTimer = 0f;
            _wanderDir = Random.insideUnitCircle.normalized;
        }

        Vector2 target = (Vector2)Core.transform.position + _wanderDir * WanderDistance;
        Core.Movement?.MoveTowardsPosition(target);
    }
}

using UnityEngine;

/// <summary>
/// 急性谵妄 buff 效果：敌人不再以玩家为目标，随处乱走，不发射弹幕。
/// OnApply — 清除玩家目标、切换 ConfusedState（乱走）、禁用技能管理器；
/// OnRemove — 恢复技能管理器、重新定位玩家、切回 Idle/Patrol。
/// 泛用减益效果：可作为"混乱/迷惑/失智"类 debuff 的效果策略复用。
/// </summary>
[CreateAssetMenu(fileName = "DeliriumBuff", menuName = "Game/Buff Effect/Delirium (Confusion)")]
public class DeliriumBuff : BuffEffectBase
{
    public override void OnApply(GameObject target, BuffInstance buff)
    {
        var core = target.GetComponent<EnemyCore>();
        if (core == null || core.IsDead) return;

        // 已同化的随从不受影响（是自己人）
        if (core.IsAssimilated) return;

        // 不再以玩家为目标
        core.PlayerTarget = null;

        // 禁用技能（不发射弹幕）
        if (core.SkillManager != null)
            core.SkillManager.enabled = false;

        // 停止当前行为，切换到乱走状态
        if (core.StateMachine != null)
            core.StateMachine.ChangeState(new ConfusedState(core));
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        var core = target.GetComponent<EnemyCore>();
        if (core == null || core.IsDead) return;

        // 恢复技能
        if (core.SkillManager != null)
            core.SkillManager.enabled = true;

        // 重新定位玩家
        if (core.PlayerTarget == null)
        {
            var player = GameObject.FindGameObjectWithTag("Player");
            if (player != null) core.PlayerTarget = player.transform;
        }

        // 恢复正常 AI（有巡逻点则巡逻，否则空闲）
        if (core.StateMachine != null)
        {
            if (core.config != null && core.config.patrolPoints != null && core.config.patrolPoints.Count > 0)
                core.StateMachine.ChangeState(new PatrolState(core));
            else
                core.StateMachine.ChangeState(new IdleState(core));
        }
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// 急性谵妄触发体 — 由 ProjectileSkillEffect(speed=0) 原地生成。
/// Start 时给当前房间所有存活敌人挂上混乱 debuff，播放扩散环视觉后销毁。
/// </summary>
public class DeliriumTrigger : MonoBehaviour
{
    [Header("触发配置")]
    [Tooltip("要施加的混乱 debuff（DeliriumBuff 效果）")]
    [SerializeField] private BuffData _deliriumDebuff;
    [Tooltip("扩散环最大半径（视觉）")]
    [SerializeField] private float _waveRadius = 10f;
    [Tooltip("扩散动画时长（秒）")]
    [SerializeField] private float _waveDuration = 0.8f;

    private SpriteRenderer _sr;
    private Material _matInstance;

    private void Awake()
    {
        // 禁用 Projectile（原地不动、不触发命中）
        var proj = GetComponent<Projectile>();
        if (proj != null) proj.enabled = false;

        // 修复 sprite 引用丢失（运行时创建纹理序列化丢失）
        _sr = GetComponent<SpriteRenderer>();
        if (_sr != null && _sr.sprite == null)
            _sr.sprite = CreateWhiteSprite();
        if (_sr != null)
        {
            _matInstance = new Material(_sr.sharedMaterial);
            _sr.material = _matInstance;
        }
    }

    private void Start()
    {
        var proj = GetComponent<Projectile>();
        GameObject casterGO = proj != null ? proj.Caster : null;

        // 给当前房间所有存活敌人挂 debuff
        ApplyDebuffToRoom(casterGO);

        // 播放扩散环视觉后销毁
        StartCoroutine(PlayWaveAndDestroy());
    }

    /// <summary>给场景中所有存活、未同化的敌人挂混乱 debuff</summary>
    private void ApplyDebuffToRoom(GameObject caster)
    {
        if (_deliriumDebuff == null) return;

        var enemies = FindObjectsOfType<EnemyCore>();
        foreach (var enemy in enemies)
        {
            if (enemy == null || enemy.IsDead || enemy.IsAssimilated) continue;

            var buffMgr = enemy.GetComponent<BuffManager>();
            if (buffMgr == null) continue;

            buffMgr.ApplyBuff(_deliriumDebuff, caster);
        }

        Debug.Log($"[DeliriumTrigger] 已对 {enemies.Length} 个敌人施加混乱 debuff");
    }

    /// <summary>扩散环视觉动画（复用 DiffusionWave shader 的 _CurrentRadius 参数）</summary>
    private IEnumerator PlayWaveAndDestroy()
    {
        float elapsed = 0f;
        while (elapsed < _waveDuration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / _waveDuration);

            if (_matInstance != null)
            {
                _matInstance.SetFloat("_CurrentRadius", t * _waveRadius);
                _matInstance.SetFloat("_MaxRadius", _waveRadius);
                _matInstance.SetFloat("_Fade", 1f - t);
            }

            // 扩散环放大到最大半径
            if (_sr != null)
            {
                float scale = Mathf.Lerp(1f, _waveRadius * 2f, t);
                transform.localScale = new Vector3(scale, scale, 1f);
            }

            yield return null;
        }

        Destroy(gameObject);
    }

    /// <summary>生成纯白 1x1 sprite（PPU=1）</summary>
    private static Sprite CreateWhiteSprite()
    {
