using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/AcuteDelirium";
string dataDir = "Assets/Resources/Skills/Data/AcuteDelirium";
if (!AssetDatabase.IsValidFolder(skillDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "AcuteDelirium");
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "AcuteDelirium");

// ── 1. BuffEffect 资产 ──
string buffEffectPath = dataDir + "/DeliriumBuffEffect.asset";
DeliriumBuff buffEffect = AssetDatabase.LoadAssetAtPath<DeliriumBuff>(buffEffectPath);
if (buffEffect == null)
{
    buffEffect = ScriptableObject.CreateInstance<DeliriumBuff>();
    AssetDatabase.CreateAsset(buffEffect, buffEffectPath);
}
EditorUtility.SetDirty(buffEffect);
Debug.Log("BuffEffect: " + buffEffectPath);

// ── 2. BuffData 资产 ──
string buffPath = dataDir + "/DeliriumDebuff.asset";
BuffData buffData = AssetDatabase.LoadAssetAtPath<BuffData>(buffPath);
if (buffData == null)
{
    buffData = ScriptableObject.CreateInstance<BuffData>();
    AssetDatabase.CreateAsset(buffData, buffPath);
}
buffData.buffId = "delirium_debuff";
buffData.buffName = "急性谵妄";
buffData.description = "目标不再以玩家为目标，随处乱走，不发射弹幕。持续5秒。";
buffData.buffType = BuffType.Debuff;
buffData.duration = 5f;
buffData.isPermanent = false;
buffData.stackable = false;
buffData.maxStacks = 1;
buffData.stackBehavior = StackBehavior.Refresh;
buffData.effect = buffEffect;
buffData.icon = null;
EditorUtility.SetDirty(buffData);
Debug.Log("BuffData: " + buffPath + " (duration=5s)");

// ── 3. 扩散环材质（复用 DiffusionWave shader，紫色）──
Shader waveShader = Shader.Find("Custom/DiffusionWave");
if (waveShader == null) { Debug.LogError("DiffusionWave shader 未找到!"); return; }
string matPath = skillDir + "/DeliriumWave.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(waveShader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = waveShader;
mat.SetColor("_Color", new Color(0.9f, 0.5f, 1.0f, 1.0f));     // 紫色环
mat.SetColor("_ColorInner", new Color(0.7f, 0.3f, 0.9f, 0.6f));
mat.SetFloat("_RingWidth", 1.2f);
mat.SetFloat("_Distortion", 0.12f);
EditorUtility.SetDirty(mat);
Debug.Log("材质: " + matPath);

// ── 4. 触发体预制体 ──
string prefabPath = skillDir + "/DeliriumTrigger.prefab";
GameObject existing = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
if (existing == null)
{
    var go = new GameObject("DeliriumTrigger");
    var sr = go.AddComponent<SpriteRenderer>();
    sr.material = mat;
    sr.sortingOrder = 30;

    var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
    tex.SetPixel(0, 0, Color.white);
    tex.Apply();
    sr.sprite = Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);

    go.transform.localScale = new Vector3(1f, 1f, 1f);

    go.AddComponent<Projectile>();
    var trigger = go.AddComponent<DeliriumTrigger>();

    // 用 SerializedObject 设置 Inspector 参数
    var so = new SerializedObject(trigger);
    so.FindProperty("_deliriumDebuff").objectReferenceValue = buffData;
    so.FindProperty("_waveRadius").floatValue = 10f;
    so.FindProperty("_waveDuration").floatValue = 0.8f;
    so.ApplyModifiedProperties();

    var saved = PrefabUtility.SaveAsPrefabAsset(go, prefabPath);
    Debug.Log("预制体: " + (saved != null ? prefabPath : "保存失败"));
    Object.DestroyImmediate(go);
}
else
{
    Debug.Log("预制体已存在: " + prefabPath);
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 急性谵妄 Buff/材质/预制体创建完成 ===");

