using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人放玩家附近
    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length == 0) { Debug.LogError("场景无敌人!"); yield break; }
    var enemy = enemies[0];
    var player = GameObject.FindGameObjectWithTag("Player");

    player.transform.position = new Vector3(0, 0, 0);
    enemy.transform.position = new Vector3(3, 0, 0);
    Debug.Log($"敌人 @ {enemy.transform.position}, 玩家 @ {player.transform.position}");
    Debug.Log($"敌人初始状态: {enemy.StateMachine.CurrentState?.GetType().Name}");

    // 玩家施放急性谵妄
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "acute_delirium");
    if (sd == null) { Debug.LogError("acute_delirium 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已施放急性谵妄");

    // 等 1s（debuff 生效）
    yield return new WaitForSeconds(1f);

    var buffMgr = enemy.GetComponent<BuffManager>();
    bool hasDebuff = buffMgr != null && buffMgr.HasBuff("delirium_debuff");
    Debug.Log($"敌人有谵妄debuff: {hasDebuff}");
    Debug.Log($"敌人当前状态: {enemy.StateMachine.CurrentState?.GetType().Name}");
    Debug.Log($"敌人 PlayerTarget: {enemy.PlayerTarget}");
    Debug.Log($"敌人 SkillManager.enabled: {enemy.SkillManager?.enabled}");

    // 敌人是否在移动（乱走）
    Debug.Log($"敌人位置: {enemy.transform.position}");

    // 记录位置，1.5s 后再看是否移动（乱走）
    Vector3 p1 = enemy.transform.position;
    yield return new WaitForSeconds(1.5f);
    Vector3 p2 = enemy.transform.position;
    Debug.Log($"乱走测试: {p1} → {p2}, 位移 {(p2-p1).magnitude:F2}");
}

return Run();

