using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var enemy = Object.FindObjectsOfType<EnemyCore>().First();
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    enemy.transform.position = new Vector3(3, 0, 0);

    // 施放急性谵妄
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "acute_delirium");
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已施放");

    // 等 1s 确认进入混乱
    yield return new WaitForSeconds(1f);
    var buffMgr = enemy.GetComponent<BuffManager>();
    var buff = buffMgr.GetBuff("delirium_debuff");
    Debug.Log($"施放1s后: 状态={enemy.StateMachine.CurrentState?.GetType().Name}, debuff剩余={buff?.RemainingDuration:F1}");

    // 再等 5s（> debuff 时长 5s）验证过期恢复
    yield return new WaitForSeconds(5f);
    bool hasDebuff = buffMgr.HasBuff("delirium_debuff");
    Debug.Log($"6s后: debuff存在={hasDebuff}, 状态={enemy.StateMachine.CurrentState?.GetType().Name}");
    Debug.Log($"PlayerTarget恢复: {enemy.PlayerTarget != null}, SkillManager: {enemy.SkillManager?.enabled}");
    Debug.Log(hasDebuff == false && enemy.PlayerTarget != null
        ? "✅ 5s 后 debuff 过期，敌人恢复正常" : "⚠️ 恢复异常");
}

return Run();

