using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/KeratinShield";
string dataDir = "Assets/Resources/Skills/Data/KeratinShield";
if (!AssetDatabase.IsValidFolder(skillDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "KeratinShield");
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "KeratinShield");

// ── 1. 材质 ──
Shader shader = Shader.Find("Custom/KeratinShield");
if (shader == null) { Debug.LogError("KeratinShield shader 未找到!"); return; }
string matPath = skillDir + "/KeratinShield.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetColor("_Color", new Color(1.0f, 0.82f, 0.45f, 0.6f));   // 角质黄
mat.SetColor("_EdgeColor", new Color(1.0f, 0.9f, 0.6f, 0.9f));
mat.SetFloat("_ShieldRadius", 1.0f);
mat.SetFloat("_RingWidth", 0.35f);
mat.SetFloat("_Opacity", 0.7f);
mat.SetFloat("_PatternScale", 6f);
mat.SetFloat("_PulseSpeed", 3f);
EditorUtility.SetDirty(mat);
Debug.Log("材质: " + matPath);

// ── 2. Effect SO ──
string effectPath = dataDir + "/KeratinShieldEffect.asset";
KeratinShieldSkillEffect effect = AssetDatabase.LoadAssetAtPath<KeratinShieldSkillEffect>(effectPath);
if (effect == null)
{
    effect = ScriptableObject.CreateInstance<KeratinShieldSkillEffect>();
    AssetDatabase.CreateAsset(effect, effectPath);
}
var so = new SerializedObject(effect);
so.FindProperty("_duration").floatValue = 3f;
so.FindProperty("_slowFactor").floatValue = 0.5f;
so.FindProperty("_perfectWindow").floatValue = 0.3f;
so.FindProperty("_skillId").stringValue = "keratin_shield";
so.FindProperty("_shieldMaterial").objectReferenceValue = mat;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effect);
Debug.Log("Effect: " + effectPath);

// ── 3. SkillData ──
string dataPath = dataDir + "/KeratinShield.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "keratin_shield";
sd.skillName = "角质增生覆膜";
sd.description = "获得角质护盾，可抵挡弹幕和冲撞伤害。可长按持续架盾（期间不可攻击且移速降低），最长3秒。释放后0.3秒内被击中视为完美格挡，立即刷新冷却。";
sd.cooldown = 6f;
sd.castRange = 0f;
sd.damageMultiplier = 0f;
sd.maxLevel = 5;
sd.skillEffect = effect;
sd.icon = null;
EditorUtility.SetDirty(sd);
Debug.Log("SkillData: " + dataPath);

// ── 4. 注册 ──
SkillLibrary lib = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
bool found = false;
foreach (var s in lib.AllSkills)
{
    if (s != null && s.skillId == "keratin_shield") { found = true; break; }
}
if (!found)
{
    var field = typeof(SkillLibrary).GetField("_allSkills",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var list = field.GetValue(lib) as System.Collections.Generic.List<SkillData>;
    if (list != null)
    {
        list.Add(sd);
        Debug.Log("已注册到 SkillLibrary");
    }
    EditorUtility.SetDirty(lib);
}
else Debug.Log("已在 SkillLibrary 中");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 角质增生覆膜资产创建完成 ===");

