    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "keratin_shield");

    // ── 测试1：架盾挡弹幕 ──
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.2f); // 已过完美窗口，普通格挡

    // 模拟敌方弹幕命中玩家（通过 Projectile 组件触发）
    var bulletPrefab = Resources.Load<GameObject>("Prefabs/Bullet");
    if (bulletPrefab == null)
    {
        // 查找场景中已有的子弹预制体
        var allProjectiles = AssetDatabase? // 不能用 AssetDatabase in play
        Debug.LogWarning("无法加载 Bullet prefab，改用直接调用 shield.TryBlock 模拟");
    }

    float hpBefore = stats.CurrentHealth;
    // 直接调用 TryBlock 模拟弹幕命中
    var shield = player.GetComponent<KeratinShieldRuntime>();
    if (shield != null && shield.IsActive)
    {
        shield.TryBlock(); // 普通格挡（窗口已过）
    }
    yield return new WaitForSeconds(0.1f);
    float hpAfter = stats.CurrentHealth;
