    // ── 测试2：长按结束（无按键时 3s 后自动结束）──
    // 等剩余时间
    yield return new WaitForSeconds(3f);
    var shieldAfter = player.GetComponent<KeratinShieldRuntime>();
    Debug.Log($"3s 后护盾: {(shieldAfter != null && shieldAfter.IsActive)} (应 False)");
    Debug.Log($"AttackLocked: {pc.AttackLocked} (应 False), Speed: {pc.SpeedMultiplier} (应 1)");
}

return Run();

