using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();
    var skillMgr = player.GetComponent<PlayerSkillManager>();

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var shieldSd = lib.AllSkills.FirstOrDefault(s => s.skillId == "keratin_shield");
    var erodeSd = lib.AllSkills.FirstOrDefault(s => s.skillId == "erode");

    // 玩家架盾（0.2s 后完美窗口已过，普通格挡）
    shieldSd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.2f);

    // 敌人移到玩家左侧，加载 erode（投射物）技能
    var enemy = Object.FindObjectsOfType<EnemyCore>().First();
    enemy.transform.position = new Vector3(-4, 0, 0);
    enemy.SkillManager.LoadSkills(lib, "erode");
    Debug.Log($"敌人已加载 erode，玩家架盾中: {player.GetComponent<KeratinShieldRuntime>()?.IsActive}");

    float hpBefore = stats.CurrentHealth;
    // 敌人朝玩家施放弹幕
    enemy.SkillManager.TryCastSkill(0, enemy, Vector2.right);
    Debug.Log($"敌人已发射弹幕 (弹幕速度10, 距离4 → ~0.4s 命中)");

    yield return new WaitForSeconds(0.8f);
    float hpAfter = stats.CurrentHealth;
    Debug.Log($"弹幕命中后: 生命 {hpBefore} → {hpAfter} ({(hpAfter-hpBefore):F0})");
    Debug.Log(hpAfter == hpBefore ? "✅ 护盾拦截弹幕（玩家不掉血）" : "⚠️ 弹幕穿透护盾");

    var shield = player.GetComponent<KeratinShieldRuntime>();
    Debug.Log($"护盾仍在: {shield != null && shield.IsActive} (普通格挡不结束，应 True)");
}

return Run();

