    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();
    var skillMgr = player.GetComponent<PlayerSkillManager>();

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var shieldSd = lib.AllSkills.FirstOrDefault(s => s.skillId == "keratin_shield");

    // 玩家架盾
    shieldSd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.3f);

    Debug.Log($"架盾中: {player.GetComponent<KeratinShieldRuntime>()?.IsActive}");

    // 用真实 Projectile 验证拦截：手动创建一个敌方子弹放在玩家旁
    var bulletSrc = Object.FindObjectsOfType<Projectile>().FirstOrDefault(p => p.Owner == Projectile.OwnerType.Player);
    Debug.Log($"场景中玩家子弹: {bulletSrc != null}");

    // 直接实例化一个 Projectile 测试（用玩家自己的子弹，但 owner 改为 Enemy 不现实）
    // 改为：找敌人发射的子弹 prefab 途径 —— 从 erode 技能资产读取
    var erode = lib.AllSkills.FirstOrDefault(s => s.skillId == "erode")?.skillEffect as ProjectileSkillEffect;
    if (erode != null && erode.projectilePrefab != null)
    {
        var go = Object.Instantiate(erode.projectilePrefab, new Vector3(-2, 0, 0), Quaternion.identity);
        var proj = go.GetComponent<Projectile>();
        proj.Initialize(Vector2.right, 10f, 10f, Projectile.OwnerType.Enemy, player); // caster=玩家但 owner=Enemy → 命中 Player
        Debug.Log("已生成敌方子弹 → 玩家");
    }
    else
    {
        Debug.LogWarning("erode 投射物 prefab 不可用");
    }

    float hpBefore = stats.CurrentHealth;
    yield return new WaitForSeconds(0.6f); // 子弹飞行 2 单位 → 命中
    float hpAfter = stats.CurrentHealth;
    Debug.Log($"生命 {hpBefore} → {hpAfter} ({(hpAfter-hpBefore):F0})");
    Debug.Log(hpAfter == hpBefore ? "✅ 护盾拦截弹幕" : "⚠️ 弹幕命中（未拦截）");
}

return Run();

