using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    var pc = player.GetComponent<PlayerController>();

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "keratin_shield");

    // 架盾
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.3f); // 过完美窗口

    var shield = player.GetComponent<KeratinShieldRuntime>();
    Debug.Log($"架盾中: {shield?.IsActive}");

    // 第一次拦截 → 挡下并破碎
    bool block1 = shield.TryBlock();
    Debug.Log($"第一次拦截: {block1}");
    yield return new WaitForSeconds(0.1f);

    // 破碎动画中（组件可能还在）
    var shieldAfter1 = player.GetComponent<KeratinShieldRuntime>();
    Debug.Log($"挡后 IsActive: {shieldAfter1 != null && shieldAfter1.IsActive} (应 False)");
    Debug.Log($"AttackLocked: {pc.AttackLocked} (应 False)");

    // 等破碎动画结束，组件销毁
    yield return new WaitForSeconds(0.2f);
    var shieldAfter2 = player.GetComponent<KeratinShieldRuntime>();
    Debug.Log($"破碎后组件: {(shieldAfter2 != null ? "存在" : "已销毁")} (应 已销毁)");

    // 第二次拦截验证（护盾已碎，TryBlock 返回 false）
    if (shieldAfter2 != null)
    {
        bool block2 = shieldAfter2.TryBlock();
        Debug.Log($"第二次拦截: {block2} (应 False)");
    }
    else
    {
        Debug.Log("第二次拦截: 组件不存在 (护盾已碎)");
    }
    Debug.Log($"玩家存活: {player != null && player.activeInHierarchy}");
}

return Run();

