public bool TryBlock()
{
    if (!_isActive || _breaking) return false;

    bool perfect = _perfectTimer > 0f && !_perfectTriggered;

    // 挡住瞬间立即恢复施法者状态（解锁攻击+移速），破碎动画只是视觉
    RestoreCaster();

    // 命中反馈：闪白 + 破碎动画
    _hitFlash = 1f;
    _breaking = true;
    _breakTimer = 0f;
    _isActive = false;   // 已消耗，不再拦截

    if (perfect)
    {
        _perfectTriggered = true;
        ResetSkillCooldown();
    }

    return true;
}

