using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人移远+满血
    var enemy = Object.FindObjectsOfType<EnemyCore>().First();
    enemy.transform.position = new Vector3(50, 50, 0);
    enemy.Health.MaxHealth = 1000f;
    enemy.Health.Heal(1000f);
    yield return new WaitForSeconds(0.1f);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();

    // 玩家手动激活护盾（长按检测绕过：用非玩家施法方式）——直接 Activate
    var shield = player.AddComponent<KeratinShieldRuntime>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var effect = lib.AllSkills.FirstOrDefault(s => s.skillId == "keratin_shield").skillEffect as KeratinShieldSkillEffect;
    var matField = typeof(KeratinShieldSkillEffect).GetField("_shieldMaterial",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    shield.Activate(player.GetComponent<PlayerSkillManager>(), 3f, 0.5f, 0.3f, "keratin_shield", (Material)matField.GetValue(effect));

    // 敌人近战攻击玩家（冲撞拦截）
    var melee = enemy.GetComponent<MeleeAttack>();
    enemy.transform.position = new Vector3(0.8f, 0, 0);
    float hpBefore = stats.CurrentHealth;
    melee.TryAttack(player.transform);
    yield return new WaitForSeconds(0.05f);
    float hpAfter = stats.CurrentHealth;
    Debug.Log($"冲撞拦截: 生命 {hpBefore}→{hpAfter} ({(hpAfter-hpBefore):F0}, 应 0)");
    Debug.Log($"护盾已碎(只挡一次): {player.GetComponent<KeratinShieldRuntime>() == null || !player.GetComponent<KeratinShieldRuntime>().IsActive}");

    // 第二次攻击不再拦截 → 玩家掉血
    yield return new WaitForSeconds(0.1f);
    hpBefore = stats.CurrentHealth;
    melee.TryAttack(player.transform);
    yield return new WaitForSeconds(0.05f);
    hpAfter = stats.CurrentHealth;
    Debug.Log($"第二次攻击(无盾): 生命 {hpBefore}→{hpAfter} ({(hpAfter-hpBefore):F0}, 应 <0)");
    Debug.Log(hpAfter < hpBefore ? "✅ 护盾碎后攻击穿透" : "⚠️ 未穿透");
}

return Run();

