using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人移远
    foreach (var e in Object.FindObjectsOfType<EnemyCore>())
        e.transform.position = new Vector3(50, 50, 0);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();

    // 手动激活护盾（带无敌时长 1.5s）
    var shield = player.AddComponent<KeratinShieldRuntime>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var effect = lib.AllSkills.FirstOrDefault(s => s.skillId == "keratin_shield").skillEffect as KeratinShieldSkillEffect;
    var matField = typeof(KeratinShieldSkillEffect).GetField("_shieldMaterial",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    Material shieldMat = (Material)matField.GetValue(effect);
    shield.Activate(player.GetComponent<PlayerSkillManager>(), 3f, 0.5f, 0.3f, 1.5f, "keratin_shield", shieldMat);

    // 格挡一次（触发无敌）
    shield.TryBlock();
    Debug.Log($"格挡后无敌: {player.GetComponent<DamageImmunity>()?.IsImmune} (应 True)");
    Debug.Log($"剩余无敌时间: {player.GetComponent<DamageImmunity>()?.RemainingTime:F1} (应 ~1.5)");

    // 无敌期间直接造成伤害（模拟任意来源）→ 应免疫
    float hpBefore = stats.CurrentHealth;
    stats.TakeDamage(100f);
    yield return new WaitForSeconds(0.1f);
    float hpAfter = stats.CurrentHealth;
    Debug.Log($"无敌期间受伤: {hpBefore}→{hpAfter} ({(hpAfter-hpBefore):F0}, 应 0)");
    Debug.Log(hpAfter == hpBefore ? "✅ 无敌期间免疫伤害" : "⚠️ 无敌未生效");

    // 等无敌结束（1.5s）
    yield return new WaitForSeconds(1.6f);
    var immunity = player.GetComponent<DamageImmunity>();
    Debug.Log($"1.6s 后无敌: {immunity != null && immunity.IsImmune} (应 False)");

    hpBefore = stats.CurrentHealth;
    stats.TakeDamage(100f);
    yield return new WaitForSeconds(0.1f);
    hpAfter = stats.CurrentHealth;
    Debug.Log($"无敌结束后受伤: {hpBefore}→{hpAfter} ({(hpAfter-hpBefore):F0}, 应 -100)");
    Debug.Log(hpAfter < hpBefore ? "✅ 无敌结束后恢复正常受伤" : "⚠️ 异常");
}

return Run();

