using UnityEngine;

/// <summary>
/// 泛用"施加 Buff"技能效果 — 执行时给施法者自身挂上一个 buff。
/// 适合自增益类技能（护盾、强化、免疫等）：只需配置 BuffData 即可复用。
/// 右键 -> Create -> Game -> Skill Effect -> Apply Buff
/// </summary>
[CreateAssetMenu(fileName = "ApplyBuffEffect", menuName = "Game/Skill Effect/Apply Buff")]
public class ApplyBuffSkillEffect : SkillEffectBase
{
    [Header("Buff 配置")]
    [Tooltip("要施加到施法者身上的 BuffData（Buff/Debuff 均可）")]
    [SerializeField] private BuffData _buffData;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (_buffData == null)
        {
            Debug.LogWarning("ApplyBuffSkillEffect: _buffData 为空！");
            return;
        }

        var target = caster.CasterTransform.gameObject;
        var buffManager = target.GetComponent<BuffManager>();
        if (buffManager == null)
        {
            Debug.LogWarning($"ApplyBuffSkillEffect: 目标 {target.name} 没有 BuffManager！");
            return;
        }

        buffManager.ApplyBuff(_buffData, target);
    }
}

using UnityEngine;

/// <summary>
/// 镇痛阻滞运行时组件 — 挂在角色身上，处理"伤害延迟"。
/// buff 激活期间：受到伤害仅 50% 立即扣除，另外 50% 记入延迟伤害池。
/// buff 结束后：延迟伤害池转为"痛觉残留"debuff 缓慢扣除。
/// 同时提供硬直免疫标志（IgnoreStun）。
/// </summary>
public class AnalgesicBlockRuntime : MonoBehaviour
{
    /// <summary>立即扣除比例（0.5 = 一半立即扣，一半延迟）</summary>
    public float ImmediateFactor { get; set; } = 0.5f;

    /// <summary>是否激活（buff 持续期间）</summary>
    public bool IsActive { get; set; } = true;

    /// <summary>累计的延迟伤害池</summary>
    public float PendingDamage { get; private set; }

    // ── 视觉 ──
    private GameObject _visualGO;
    private Material _matInstance;

    /// <summary>激活镇痛（创建视觉）</summary>
    public void Activate(Material fieldMaterial)
    {
        CreateVisual(fieldMaterial);
    }

    /// <summary>把伤害拆分为立即 + 延迟，返回立即扣除部分</summary>
    public float SplitDamage(float damage)
    {
        if (!IsActive || damage <= 0f) return damage;

        float immediate = damage * ImmediateFactor;
        float delayed = damage - immediate;
        if (delayed > 0f)
            PendingDamage += delayed;
        return immediate;
    }

    /// <summary>取走整个延迟伤害池（并清零），供"痛觉残留"debuff 使用</summary>
    public float TakePendingDamage()
    {
        float total = PendingDamage;
        PendingDamage = 0f;
        return total;
    }

    /// <summary>直接扣减池中伤害（痛觉残留 DOT 每 tick 调用）</summary>
    public void ConsumePending(float amount)
    {
        PendingDamage = Mathf.Max(0f, PendingDamage - amount);
    }

    /// <summary>清除延迟池（无残留伤害时调用）</summary>
    public void ClearPending()
    {
        PendingDamage = 0f;
    }

    /// <summary>是否还有未结算的延迟伤害</summary>
    public bool HasPending => PendingDamage > 0.01f;

    private void CreateVisual(Material fieldMaterial)
    {
        _visualGO = new GameObject("AnalgesicField");
        _visualGO.transform.SetParent(transform);
        _visualGO.transform.position = transform.position;

        var sr = _visualGO.AddComponent<SpriteRenderer>();
        if (fieldMaterial != null)
        {
            _matInstance = new Material(fieldMaterial);
            sr.material = _matInstance;
        }
        sr.sprite = CreateWhiteSprite();
        sr.sortingOrder = 80;
    }

    private void Update()
    {
        // 视觉跟随
        if (_visualGO != null)
            _visualGO.transform.position = transform.position;
    }

    private void OnDestroy()
    {
        if (_visualGO != null)
            Destroy(_visualGO);
    }

    /// <summary>生成纯白 1x1 sprite（PPU=1）</summary>
    private static Sprite CreateWhiteSprite()
    {
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
    }
}

using UnityEngine;

/// <summary>
/// 镇痛阻滞 buff 效果：
/// OnApply — 激活 AnalgesicBlockRuntime（伤害 50% 立即扣、50% 延迟），
///           角色免疫硬直（PlayerController.IgnoreStun = true）。
/// OnRemove — 把延迟伤害池转为"痛觉残留"debuff 缓慢扣除，恢复硬直免疫。
/// 泛用减益/增益效果：作为"伤害延迟"类 buff 的效果策略复用。
/// </summary>
[CreateAssetMenu(fileName = "AnalgesicBlockBuff", menuName = "Game/Buff Effect/Analgesic Block")]
public class AnalgesicBlockBuff : BuffEffectBase
{
    [Header("镇痛配置")]
    [Tooltip("立即扣除比例（0.5 = 一半立即扣一半延迟）")]
    public float immediateFactor = 0.5f;

    [Tooltip("buff 结束后的痛觉残留 debuff（DamageOverTime 风格，动态总量）")]
    public BuffData afterDebuff;

    [Tooltip("镇痛光膜材质（null=无视觉）")]
    public Material fieldMaterial;

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        // 激活/创建伤害延迟运行时组件
        var runtime = target.GetComponent<AnalgesicBlockRuntime>();
        if (runtime == null)
            runtime = target.AddComponent<AnalgesicBlockRuntime>();

        runtime.ImmediateFactor = immediateFactor;
        runtime.IsActive = true;
        runtime.Activate(fieldMaterial);

        // 硬直免疫（玩家）
        var pc = target.GetComponent<PlayerController>();
        if (pc != null)
            pc.IgnoreStun = true;
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        var runtime = target.GetComponent<AnalgesicBlockRuntime>();

        // 恢复硬直免疫
        var pc = target.GetComponent<PlayerController>();
        if (pc != null)
            pc.IgnoreStun = false;

        // 有延迟伤害 → 转成"痛觉残留"debuff 缓慢扣除
        if (runtime != null && runtime.HasPending && afterDebuff != null)
        {
            var buffManager = target.GetComponent<BuffManager>();
            if (buffManager != null)
                buffManager.ApplyBuff(afterDebuff, buff.Caster);
        }

        // 清理运行时组件（延迟池已被 DOT 取走或清零）
        if (runtime != null)
            Object.Destroy(runtime);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 痛觉残留 debuff 效果 — buff 生效期间把"镇痛阻滞"积累的延迟伤害缓慢扣除。
/// 总量在 OnApply 时从 AnalgesicBlockRuntime 读取（动态），按 tick 匀速扣完。
/// 作为"延迟伤害结算"类 debuff 的效果策略复用。
/// </summary>
[CreateAssetMenu(fileName = "AnalgesicAfterBuff", menuName = "Game/Buff Effect/Analgesic Aftermath")]
public class AnalgesicAfterBuff : BuffEffectBase
{
    [Tooltip("结算间隔（秒）")]
    public float tickInterval = 0.5f;

    // buff → 剩余总伤害
    private static readonly Dictionary<BuffInstance, float> _remaining = new();
    // buff → tick 计时
    private static readonly Dictionary<BuffInstance, float> _timers = new();

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        // 从镇痛运行时组件取走延迟伤害池作为总伤害
        float total = 0f;
        var runtime = target.GetComponent<AnalgesicBlockRuntime>();
        if (runtime != null)
            total = runtime.TakePendingDamage();

        _remaining[buff] = total;
        _timers[buff] = 0f;
    }

    public override void OnTick(GameObject target, BuffInstance buff, float deltaTime)
    {
        if (!_remaining.TryGetValue(buff, out float total) || total <= 0f)
            return;

        _timers.TryGetValue(buff, out float timer);
        timer += deltaTime;
        if (timer < tickInterval)
        {
            _timers[buff] = timer;
            return;
        }

        // 每 tick 扣除量 = 总伤害 / 总时长 × tickInterval（匀速）
        float duration = Mathf.Max(buff.Data.duration, 0.1f);
        float perTick = total / duration * tickInterval;

        // 最后一 tick 不超总量
        perTick = Mathf.Min(perTick, total);

        // 扣血 + 同步池（保持可视化）
        var damageable = target.GetComponent<IDamageable>();
        damageable?.TakeDamage(perTick);

        var runtime = target.GetComponent<AnalgesicBlockRuntime>();
        if (runtime != null) runtime.ConsumePending(perTick);

        _remaining[buff] = total - perTick;
        _timers[buff] = timer - tickInterval;
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        _remaining.Remove(buff);
        _timers.Remove(buff);
    }
}

