using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/AnalgesicBlock";
string dataDir = "Assets/Resources/Skills/Data/AnalgesicBlock";
if (!AssetDatabase.IsValidFolder(skillDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "AnalgesicBlock");
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "AnalgesicBlock");

// ── 1. 材质 ──
Shader shader = Shader.Find("Custom/AnalgesicField");
if (shader == null) { Debug.LogError("AnalgesicField shader 未找到!"); return; }
string matPath = skillDir + "/AnalgesicField.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetColor("_Color", new Color(0.6f, 0.85f, 1.0f, 0.35f));
mat.SetColor("_EdgeColor", new Color(0.8f, 0.95f, 1.0f, 0.6f));
mat.SetFloat("_FieldRadius", 1.1f);
mat.SetFloat("_Opacity", 0.6f);
mat.SetFloat("_PulseSpeed", 2.5f);
