using UnityEditor;
using UnityEngine;

string dataDir = "Assets/Resources/Skills/Data/AnalgesicBlock";

// ── 1. Effect SO（ApplyBuffSkillEffect）──
string effectPath = dataDir + "/AnalgesicBlockEffect.asset";
ApplyBuffSkillEffect effect = AssetDatabase.LoadAssetAtPath<ApplyBuffSkillEffect>(effectPath);
if (effect == null)
{
    effect = ScriptableObject.CreateInstance<ApplyBuffSkillEffect>();
    AssetDatabase.CreateAsset(effect, effectPath);
}
var so = new SerializedObject(effect);
so.FindProperty("_buffData").objectReferenceValue =
    AssetDatabase.LoadAssetAtPath<BuffData>(dataDir + "/AnalgesicBlockBuff.asset");
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effect);
Debug.Log("Effect: " + effectPath);

// ── 2. SkillData ──
string dataPath = dataDir + "/AnalgesicBlock.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "analgesic_block";
sd.skillName = "镇痛阻滞";
sd.description = "获得镇痛增益：接下来12秒受到的伤害仅50%立即扣除，另外50%在技能结束后以debuff形式缓慢扣除。技能持续期间不产生硬直。";
sd.cooldown = 20f;
sd.castRange = 0f;
sd.damageMultiplier = 0f;
sd.maxLevel = 3;
sd.skillEffect = effect;
sd.icon = null;
EditorUtility.SetDirty(sd);
Debug.Log("SkillData: " + dataPath);

// ── 3. 注册 ──
SkillLibrary lib = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
bool found = false;
foreach (var s in lib.AllSkills)
{
    if (s != null && s.skillId == "analgesic_block") { found = true; break; }
}
if (!found)
{
    var field = typeof(SkillLibrary).GetField("_allSkills",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var list = field.GetValue(lib) as System.Collections.Generic.List<SkillData>;
    if (list != null)
    {
        list.Add(sd);
        Debug.Log("已注册到 SkillLibrary");
    }
    EditorUtility.SetDirty(lib);
}
else Debug.Log("已在 SkillLibrary 中");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 镇痛阻滞技能注册完成 ===");

