args.script:
using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人移远
    foreach (var e in Object.FindObjectsOfType<EnemyCore>())
        e.transform.position = new Vector3(50, 50, 0);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();
    var skillMgr = player.GetComponent<PlayerSkillManager>();
    var pc = player.GetComponent<PlayerController>();

    // 施放镇痛阻滞（ApplyBuff 给玩家挂 12s buff）
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "analgesic_block");
    if (sd == null) { Debug.LogError("analgesic_block 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.2f);

    // 检查 buff 和运行时组件
    var buffMgr = player.GetComponent<BuffManager>();
    bool hasBuff = buffMgr.HasBuff("analgesic_block");
    var runtime = player.GetComponent<AnalgesicBlockRuntime>();
    Debug.Log($"镇痛buff: {hasBuff}, 运行时激活: {runtime?.IsActive}, IgnoreStun: {pc.IgnoreStun}");

    // 受伤 100 → 应只扣 50
    float hpBefore = stats.CurrentHealth;
    stats.TakeDamage(100f);
    yield return new WaitForSeconds(0.1f);
    float hpAfter = stats.CurrentHealth;
    Debug.Log($"受伤100: 生命 {hpBefore}→{hpAfter} (扣 {(hpBefore-hpAfter):F0}, 应 50)");
    Debug.Log($"延迟池: {runtime?.PendingDamage:F0} (应 50)");

    // 再受伤 60 → 扣 30，池 +30
    hpBefore = stats.CurrentHealth;
    stats.TakeDamage(60f);
    yield return new WaitForSeconds(0.1f);
    hpAfter = stats.CurrentHealth;
    Debug.Log($"受伤60: 扣 {(hpBefore-hpAfter):F0} (应 30), 延迟池: {runtime?.PendingDamage:F0} (应 80)");

    // 硬直免疫测试（模拟 AoE 眩晕）
    pc.IgnoreStun = true; // 已经由 buff 设置
    Debug.Log($"IgnoreStun 由 buff 设置: {pc.IgnoreStun}");
}

return Run();

