using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    var stats = player.GetComponent<PlayerStats>();
    var buffMgr = player.GetComponent<BuffManager>();

    // 检查 buff 剩余时间
    var buff = buffMgr.GetBuff("analgesic_block");
    Debug.Log($"镇痛buff 剩余: {buff?.RemainingDuration:F1}s");

    // 等 buff 结束（12s - 已过 ~0.5s ≈ 11.5s）
    yield return new WaitForSeconds(12f);

    bool hasBlock = buffMgr.HasBuff("analgesic_block");
    bool hasAfter = buffMgr.HasBuff("analgesic_aftermath");
    var runtime = player.GetComponent<AnalgesicBlockRuntime>();
    Debug.Log($"12s后: 镇痛buff={hasBlock} (应False), 痛觉残留={hasAfter} (应True), 运行时={(runtime != null ? "存在" : "已移除")} (应已移除)");
    Debug.Log($"IgnoreStun 恢复: {player.GetComponent<PlayerController>().IgnoreStun} (应False)");

    // 观察残留 DOT 扣血（5s 内扣完 80）
    if (hasAfter)
    {
        float start = stats.CurrentHealth;
        yield return new WaitForSeconds(2.5f);
        float mid = stats.CurrentHealth;
        Debug.Log($"残留DOT 2.5s: 扣 {(start-mid):F1} (80 总量应扣 ~40)");
        yield return new WaitForSeconds(3f);
        float end = stats.CurrentHealth;
        Debug.Log($"残留DOT 5.5s: 总扣 {(start-end):F1} (应 ~80)");
        bool afterGone = !buffMgr.HasBuff("analgesic_aftermath");
        Debug.Log($"残留debuff 过期: {afterGone}");
    }
}

return Run();

