using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();
    var buffMgr = player.GetComponent<BuffManager>();
    var pc = player.GetComponent<PlayerController>();

    // 施放镇痛阻滞
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "analgesic_block");
    sd.skillEffect.Execute(player.GetComponent<PlayerSkillManager>(), Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.2f);

    // 受伤积累延迟池
    stats.TakeDamage(100f);
    stats.TakeDamage(100f);
    yield return new WaitForSeconds(0.1f);
    var runtime = player.GetComponent<AnalgesicBlockRuntime>();
    Debug.Log($"延迟池: {runtime.PendingDamage:F0} (应 100)");

    // 手动移除镇痛 buff → 应触发转 DOT
    buffMgr.RemoveBuffById("analgesic_block");
    yield return new WaitForSeconds(0.3f);

    bool hasAfter = buffMgr.HasBuff("analgesic_aftermath");
    Debug.Log($"痛觉残留: {hasAfter} (应True)");
    Debug.Log($"IgnoreStun 恢复: {pc.IgnoreStun} (应False)");
    Debug.Log($"运行时移除: {player.GetComponent<AnalgesicBlockRuntime>() == null} (应True)");

    // 观察 DOT 扣血（5s 内扣完 100）
    if (hasAfter)
    {
        float start = stats.CurrentHealth;
        yield return new WaitForSeconds(2.5f);
        float mid = stats.CurrentHealth;
        Debug.Log($"DOT 2.5s 扣: {(start-mid):F1} (应 ~50)");
        yield return new WaitForSeconds(3f);
        float end = stats.CurrentHealth;
        Debug.Log($"DOT 总扣: {(start-end):F1} (应 ~100)");
        Debug.Log($"残留过期: {!buffMgr.HasBuff("analgesic_aftermath")}");
    }
}

return Run();

