using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/PeritonealDialysis";
string dataDir = "Assets/Resources/Skills/Data/PeritonealDialysis";
if (!AssetDatabase.IsValidFolder(skillDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "PeritonealDialysis");
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "PeritonealDialysis");

// ── 1. 材质 ──
Shader shader = Shader.Find("Custom/PurifyWave");
if (shader == null) { Debug.LogError("PurifyWave shader 未找到!"); return; }
string matPath = skillDir + "/PurifyWave.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetColor("_Color", new Color(0.7f, 1.0f, 0.9f, 0.8f));
mat.SetColor("_EdgeColor", new Color(1.0f, 1.0f, 1.0f, 0.9f));
mat.SetFloat("_MaxRadius", 1.75f);
mat.SetFloat("_Opacity", 0.8f);
EditorUtility.SetDirty(mat);
Debug.Log("材质: " + matPath);

// ── 2. BuffEffect ──
string effectPath = dataDir + "/PeritonealDialysisBuffEffect.asset";
PeritonealDialysisBuff buffEffect = AssetDatabase.LoadAssetAtPath<PeritonealDialysisBuff>(effectPath);
if (buffEffect == null)
{
    buffEffect = ScriptableObject.CreateInstance<PeritonealDialysisBuff>();
    AssetDatabase.CreateAsset(buffEffect, effectPath);
}
buffEffect.healPerDebuff = 20f;
buffEffect.purifyMaterial = mat;
EditorUtility.SetDirty(buffEffect);
Debug.Log("BuffEffect: " + effectPath);

// ── 3. BuffData（增益，短时 1s 显示净化状态）──
string buffPath = dataDir + "/PeritonealDialysisBuff.asset";
BuffData buffData = AssetDatabase.LoadAssetAtPath<BuffData>(buffPath);
if (buffData == null)
{
    buffData = ScriptableObject.CreateInstance<BuffData>();
    AssetDatabase.CreateAsset(buffData, buffPath);
}
buffData.buffId = "peritoneal_dialysis";
buffData.buffName = "腹膜透析";
buffData.description = "清除自身所有可净化的负面效果，每清除一个回复20点生命。藏品的debuff不可清除。";
buffData.buffType = BuffType.Buff;
buffData.duration = 1f;               // 净化状态显示时长（效果在 OnApply 立即完成）
buffData.isPermanent = false;
buffData.stackable = false;
buffData.maxStacks = 1;
buffData.stackBehavior = StackBehavior.Refresh;
buffData.effect = buffEffect;
buffData.icon = null;
EditorUtility.SetDirty(buffData);
Debug.Log("BuffData: " + buffPath);

// ── 4. ApplyBuffSkillEffect SO ──
string skillEffectPath = dataDir + "/PeritonealDialysisEffect.asset";
ApplyBuffSkillEffect skillEffect = AssetDatabase.LoadAssetAtPath<ApplyBuffSkillEffect>(skillEffectPath);
if (skillEffect == null)
{
    skillEffect = ScriptableObject.CreateInstance<ApplyBuffSkillEffect>();
    AssetDatabase.CreateAsset(skillEffect, skillEffectPath);
}
var so = new SerializedObject(skillEffect);
so.FindProperty("_buffData").objectReferenceValue = buffData;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(skillEffect);
Debug.Log("SkillEffect: " + skillEffectPath);

// ── 5. SkillData ──
string dataPath = dataDir + "/PeritonealDialysis.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "peritoneal_dialysis";
sd.skillName = "腹膜透析";
sd.description = "清除自身所有可净化的负面效果（藏品的debuff不可清除），并根据清除数量回复生命（每个20点）。";
sd.cooldown = 18f;
sd.castRange = 0f;
sd.damageMultiplier = 0f;
sd.maxLevel = 5;
sd.skillEffect = skillEffect;
sd.icon = null;
EditorUtility.SetDirty(sd);
Debug.Log("SkillData: " + dataPath);

// ── 6. 注册 ──
SkillLibrary lib = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
bool found = false;
foreach (var s in lib.AllSkills)
{
    if (s != null && s.skillId == "peritoneal_dialysis") { found = true; break; }
}
if (!found)
{
    var field = typeof(SkillLibrary).GetField("_allSkills",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var list = field.GetValue(lib) as System.Collections.Generic.List<SkillData>;
    if (list != null)
    {
        list.Add(sd);
        Debug.Log("已注册到 SkillLibrary");
    }
    EditorUtility.SetDirty(lib);
}
else Debug.Log("已在 SkillLibrary 中");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 腹膜透析资产创建完成 ===");

