using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人移远
    foreach (var e in Object.FindObjectsOfType<EnemyCore>())
        e.transform.position = new Vector3(50, 50, 0);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    var stats = player.GetComponent<PlayerStats>();
    var buffMgr = player.GetComponent<BuffManager>();
    var skillMgr = player.GetComponent<PlayerSkillManager>();

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "peritoneal_dialysis");
    if (sd == null) { Debug.LogError("peritoneal_dialysis 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    // ── 给玩家挂 2 个可净化 debuff ──
    // 用高渗裂解 debuff（hypertonic_lysate_debuff）和谵妄 debuff（delirium_debuff）
    var lysateBuff = lib.AllSkills.FirstOrDefault(s => s.skillId == "hypertonic_lysate");
    // 加载 BuffData 资产
    var lysateDebuff = Resources.Load<BuffData>("Skills/Data/HypertonicLysate/LysateDebuff");
    var deliriumDebuff = Resources.Load<BuffData>("Skills/Data/AcuteDelirium/DeliriumDebuff");
    if (lysateDebuff != null) buffMgr.ApplyBuff(lysateDebuff, player);
    if (deliriumDebuff != null) buffMgr.ApplyBuff(deliriumDebuff, player);
    yield return new WaitForSeconds(0.2f);
    Debug.Log($"施放前 debuff: 裂解={buffMgr.HasBuff("hypertonic_lysate_debuff")}, 谵妄={buffMgr.HasBuff("delirium_debuff")}");

    // ── 玩家扣血（方便观察回血）──
    stats.TakeDamage(60f);
    yield return new WaitForSeconds(0.1f);
    float hpBefore = stats.CurrentHealth;
    Debug.Log($"施放前生命: {hpBefore}");

    // ── 施放腹膜透析 ──
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    yield return new WaitForSeconds(0.3f);

    // 检查：debuff 清除 + 回血（2 个 debuff × 20 = 40）
    float hpAfter = stats.CurrentHealth;
    Debug.Log($"施放后: 裂解={buffMgr.HasBuff("hypertonic_lysate_debuff")} (应False), 谵妄={buffMgr.HasBuff("delirium_debuff")} (应False)");
    Debug.Log($"回血: {hpBefore}→{hpAfter} (+{hpAfter-hpBefore:F0}, 应 +40)");
}

return Run();

