using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 敌人移远
    foreach (var e in Object.FindObjectsOfType<EnemyCore>())
        e.transform.position = new Vector3(50, 50, 0);

    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "intestinal_peristalsis");
    if (sd == null) { Debug.LogError("intestinal_peristalsis 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    // 施放（扩散波，速度18 半径8 → 0.44s 扩散完）
    sd.skillEffect.Execute(player.GetComponent<PlayerSkillManager>(), Vector2.right, 1f, Projectile.OwnerType.Player);

    // 0.25s 扩散中段截图
    yield return new WaitForSeconds(0.25f);

    UnityTcp.Editor.Tools.ManageScreenshot.BeginCapture(1f);
    yield return new WaitForSeconds(0.05f);
    string path = UnityTcp.Editor.Tools.ManageScreenshot.EndCaptureToGif(
        System.IO.Path.Combine(Application.dataPath, "../screenshots/PeristalsisV2.png"), 1, 128);
    Debug.Log($"截图: {path}");
}

return Run();

