using UnityEditor;
using UnityEngine;

string dataDir = "Assets/Resources/Skills/Data/CapsularBurst";
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "CapsularBurst");

// 复用肠管蠕动冲击的白色气浪材质
Material waveMat = AssetDatabase.LoadAssetAtPath<Material>(
    "Assets/Prefabs/SkillAsset/IntestinalPeristalsis/IntestinalPeristalsisWave.mat");
if (waveMat == null) { Debug.LogError("气浪材质未找到!"); return; }

// ── 1. Effect SO（SlideSkillEffect 配置）──
string effectPath = dataDir + "/CapsularBurstEffect.asset";
SlideSkillEffect effect = AssetDatabase.LoadAssetAtPath<SlideSkillEffect>(effectPath);
if (effect == null)
{
    effect = ScriptableObject.CreateInstance<SlideSkillEffect>();
    AssetDatabase.CreateAsset(effect, effectPath);
}
var so = new SerializedObject(effect);
// 滑移：短距突进
so.FindProperty("_distance").floatValue = 3.5f;
so.FindProperty("_speed").floatValue = 20f;
so.FindProperty("_immuneDuration").floatValue = 0.4f;
so.FindProperty("_trailMaterial").objectReferenceValue = null;
// 命中检测（冲撞伤害用 carryDamage）
so.FindProperty("_carryEnemies").boolValue = true;
so.FindProperty("_carryRadius").floatValue = 1.5f;
so.FindProperty("_carryDamage").floatValue = 30f;   // 冲撞伤害
so.FindProperty("_wallDamage").floatValue = 0f;
so.FindProperty("_carriedInvincible").boolValue = false;
// 爆发冲击
so.FindProperty("_autoAimNearest").boolValue = true;   // 自动锁最近敌人
so.FindProperty("_burstOnHit").boolValue = true;       // 命中释放气浪
so.FindProperty("_burstRadius").floatValue = 5f;
so.FindProperty("_burstPushForce").floatValue = 12f;   // 推开力度
so.FindProperty("_burstWaveMaterial").objectReferenceValue = waveMat;
so.ApplyModifiedProperties();
EditorUtility.SetDirty(effect);
Debug.Log("Effect: " + effectPath);

// ── 2. SkillData ──
string dataPath = dataDir + "/CapsularBurst.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "capsular_burst";
sd.skillName = "包膜爆发冲击";
sd.description = "瞬间短距突进冲撞最近的敌人并造成伤害；命中后周身释放气浪，推开周边敌方单位。";
sd.cooldown = 8f;
sd.castRange = 0f;
sd.damageMultiplier = 1f;
sd.maxLevel = 5;
sd.skillEffect = effect;
sd.icon = null;
EditorUtility.SetDirty(sd);
Debug.Log("SkillData: " + dataPath);

// ── 3. 注册 ──
SkillLibrary lib = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
bool found = false;
foreach (var s in lib.AllSkills)
{
    if (s != null && s.skillId == "capsular_burst") { found = true; break; }
}
if (!found)
{
    var field = typeof(SkillLibrary).GetField("_allSkills",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var list = field.GetValue(lib) as System.Collections.Generic.List<SkillData>;
    if (list != null)
    {
        list.Add(sd);
        Debug.Log("已注册到 SkillLibrary");
    }
    EditorUtility.SetDirty(lib);
}
else Debug.Log("已在 SkillLibrary 中");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== 包膜爆发冲击资产创建完成 ===");

