args.script:
using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 布置：玩家在 (0,0)，最近敌人 (3,0)，远处敌人 (6,2) 验证推开
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length < 2) { Debug.LogError($"需要2个敌人，当前{enemies.Length}"); yield break; }
    enemies[0].transform.position = new Vector3(3, 0, 0);
    enemies[1].transform.position = new Vector3(6, 2, 0);
    // 满血
    foreach (var e in enemies)
    {
        e.Health.MaxHealth = 1000f;
        e.Health.Heal(1000f);
    }
    yield return new WaitForSeconds(0.2f);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "capsular_burst");
    if (sd == null) { Debug.LogError("capsular_burst 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    // 记录敌人位置
    Vector3 e0Start = enemies[0].transform.position;
    Vector3 e1Start = enemies[1].transform.position;

    // 玩家施放（自动锁最近敌人 = 敌人0）
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已施放包膜爆发冲击");

    // 等冲刺完成 + 爆发（0.35s 位移 + 0.4s 气浪）
    yield return new WaitForSeconds(0.8f);

    // 检查敌人0 受伤（冲撞 30）
    Debug.Log($"敌人0(最近): 生命={enemies[0].Health.CurrentHealth} (1000-30=970?)");
    Debug.Log($"敌人0 被推开位移: {(enemies[0].transform.position - e0Start).magnitude:F2}");
    Debug.Log($"敌人1(周边) 被推开位移: {(enemies[1].transform.position - e1Start).magnitude:F2}");
    Debug.Log($"玩家位置: {player.transform.position}");
}

return Run();

