using UnityEditor;
using UnityEngine;

string srcPath = "Assets/TJGenerators/History/Sprite_20260811_200321.png";
string iconPath = "Assets/Resources/Skills/Data/CapsularBurst/Icon.png";

Texture2D src = AssetDatabase.LoadAssetAtPath<Texture2D>(srcPath);
if (src == null) { Debug.LogError("源图标未找到!"); return; }
Debug.Log($"源尺寸: {src.width}x{src.height}");

// 缩放 256
int size = 256;
Texture2D resized = new Texture2D(size, size, TextureFormat.RGBA32, false);
RenderTexture rt = RenderTexture.GetTemporary(size, size, 0, RenderTextureFormat.ARGB32);
Graphics.Blit(src, rt);
RenderTexture.active = rt;
resized.ReadPixels(new Rect(0, 0, size, size), 0, 0);
resized.Apply();
RenderTexture.active = null;
RenderTexture.ReleaseTemporary(rt);

System.IO.File.WriteAllBytes(System.IO.Path.Combine(Application.dataPath, "..", iconPath), resized.EncodeToPNG());
Object.DestroyImmediate(resized);
AssetDatabase.Refresh();

TextureImporter importer = (TextureImporter)AssetImporter.GetAtPath(iconPath);
if (importer != null)
{
    importer.textureType = TextureImporterType.Sprite;
    importer.spriteImportMode = SpriteImportMode.Single;
    importer.SaveAndReimport();
}

Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>(iconPath);
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>("Assets/Resources/Skills/Data/CapsularBurst/CapsularBurst.asset");
sd.icon = sprite;
EditorUtility.SetDirty(sd);
AssetDatabase.SaveAssets();
