using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    // 布置：玩家 (0,0)，最近敌人 (3,0)，周边敌人 (5,1)
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    player.GetComponent<Rigidbody2D>().velocity = Vector2.zero;

    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length < 2) { Debug.LogError($"需要2个敌人，当前{enemies.Length}"); yield break; }
    enemies[0].transform.position = new Vector3(3, 0, 0);
    enemies[1].transform.position = new Vector3(5, 1, 0);
    foreach (var e in enemies)
    {
        e.Health.MaxHealth = 1000f;
        e.Health.Heal(1000f);
        var rb = e.GetComponent<Rigidbody2D>();
        if (rb != null) rb.velocity = Vector2.zero;
    }
    yield return new WaitForSeconds(0.2f);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "capsular_burst");

    // 记录玩家起点
    Vector3 playerStart = player.transform.position;

    // 施放
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已施放包膜爆发冲击");

    // 等冲刺 + 爆发 + 推开完成
    yield return new WaitForSeconds(0.8f);

    // 玩家最终位置（应停在冲刺终点附近，不被弹回/碰走）
    Vector3 playerEnd = player.transform.position;
    float playerDisp = Vector2.Distance(playerStart, playerEnd);
    Debug.Log($"玩家: 起点 {playerStart} → 终点 {playerEnd}, 位移 {playerDisp:F2} (冲刺距离 3.5 附近)");
    Debug.Log($"敌人0 生命: {enemies[0].Health.CurrentHealth} (1000-30=970?)");
    Debug.Log($"敌人1 被推开位移: {Vector2.Distance(enemies[1].transform.position, new Vector3(5,1,0)):F2}");
}

return Run();

