    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);

    // 立即检查 SlideRuntime 状态
    var slide = player.GetComponent<SlideRuntime>();
    if (slide == null) { Debug.LogError("SlideRuntime 未生成!"); yield break; }
    var type = slide.GetType();
    var isActive = (bool)type.GetField("_isActive", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(slide);
    var dir = (Vector2)type.GetField("_direction", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(slide);
    var traveled = (float)type.GetField("_traveled", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(slide);
    var burstOnHit = (bool)type.GetField("_burstOnHit", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(slide);
    var carryEnabled = (bool)type.GetField("_carryEnabled", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(slide);
    var rbType = player.GetComponent<Rigidbody2D>().bodyType;
    Debug.Log($"isActive={isActive}, dir={dir}, traveled={traveled:F2}, burstOnHit={burstOnHit}, carryEnabled={carryEnabled}, rbType={rbType}");

    yield return new WaitForSeconds(0.3f);
    var after = player.GetComponent<SlideRuntime>();
    Debug.Log($"0.3s 后 SlideRuntime: {(after != null ? "存在" : "已销毁")}");
