using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);
    player.GetComponent<Rigidbody2D>().velocity = Vector2.zero;

    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length == 0) { Debug.LogError("无敌人!"); yield break; }
    var enemy = enemies[0];
    enemy.transform.position = new Vector3(3, 0, 0);
    enemy.Health.MaxHealth = 1000f;
    enemy.Health.Heal(1000f);
    var erb = enemy.GetComponent<Rigidbody2D>();
    if (erb != null) erb.velocity = Vector2.zero;
    yield return new WaitForSeconds(0.2f);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "capsular_burst");

    Vector3 playerStart = player.transform.position;
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已施放");

    yield return new WaitForSeconds(0.6f);

    Vector3 playerEnd = player.transform.position;
    float disp = Vector2.Distance(playerStart, playerEnd);
    Debug.Log($"玩家位移: {disp:F2} (应 ~3.0 停在敌人处)");
    Debug.Log($"敌人生命: {enemy.Health.CurrentHealth} (应 970)");
    Debug.Log($"冲刺后刚体: {player.GetComponent<Rigidbody2D>().bodyType} (应 Dynamic)");
    Debug.Log($"冲刺后collider: {player.GetComponent<Collider2D>().enabled} (应 True)");

    // 稳定性验证
    Vector3 stablePos = player.transform.position;
    yield return new WaitForSeconds(0.5f);
    float drift = Vector2.Distance(stablePos, player.transform.position);
    Debug.Log($"0.5s 漂移: {drift:F3} (应≈0)");
    Debug.Log(drift < 0.3f ? "✅ 碰撞后停留原地不乱窜" : "⚠️ 仍乱窜");
}

return Run();

