using System.Collections;
using UnityEngine;

/// <summary>
/// 线粒体生物光子辐散 — 垂直能量光柱组件。
/// 生成后持续存在，最多对范围内敌人造成 maxTicks 段伤害；
/// 单段伤害 = baseDamage + 施法者基础攻击力。
/// 只伤害敌方阵营（ownerType 决定），天然不伤害玩家、仆从、己方弹幕。
/// 多道光柱可同时命中同一敌人（各自独立 tick，无衰减）。
/// </summary>
public class PhotonBeam : MonoBehaviour
{
    [Header("光柱配置")]
    [Tooltip("伤害半径")]
    [SerializeField] private float _radius = 1.2f;
    [Tooltip("单段基础伤害（再加施法者攻击力）")]
    [SerializeField] private float _baseDamage = 20f;
    [Tooltip("每段伤害间隔（秒）")]
    [SerializeField] private float _tickInterval = 0.3f;
    [Tooltip("最大伤害段数（8=8段）")]
    [SerializeField] private int _maxTicks = 8;

    // ── 运行时状态 ──
    private Projectile.OwnerType _ownerType;
    private float _attackStrength;
    private int _ticksDone;
    private bool _initialized;

    // ── 视觉 ──
    private SpriteRenderer _sr;
    private Material _matInstance;

    /// <summary>初始化光柱</summary>
    public void Initialize(Projectile.OwnerType ownerType, float attackStrength)
    {
        _ownerType = ownerType;
        _attackStrength = attackStrength;
        _initialized = true;
    }

    private void Start()
    {
        _sr = GetComponent<SpriteRenderer>();
        if (_sr != null && _sr.material != null)
        {
            _matInstance = new Material(_sr.sharedMaterial);
            _sr.material = _matInstance;
        }
    }

    private IEnumerator TickRoutine()
    {
        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        float damage = _baseDamage + _attackStrength;

        while (_ticksDone < _maxTicks)
        {
            // 每段伤害
            Collider2D[] hits = Physics2D.OverlapCircleAll(transform.position, _radius, ~0);
            foreach (var hit in hits)
            {
                if (hit == null || !hit.CompareTag(targetTag)) continue;

                // 跳过死亡/已同化（同化后 tag 变 Player，天然跳过）
                var enemy = hit.GetComponent<EnemyCore>();
                if (enemy != null && enemy.IsDead) continue;

                if (hit.TryGetComponent<IDamageable>(out var d))
                    d.TakeDamage(damage);
            }

            _ticksDone++;

            // 视觉脉冲反馈
            if (_matInstance != null)
                _matInstance.SetFloat("_Flash", 1f);

            yield return new WaitForSeconds(_tickInterval);
        }

        Destroy(gameObject);
    }

    private void Update()
    {
        if (!_initialized) return;

        // 视觉脉冲衰减 + 持续旋转光效
        if (_matInstance != null)
        {
            float flash = _matInstance.GetFloat("_Flash");
            if (flash > 0f)
                _matInstance.SetFloat("_Flash", Mathf.MoveTowards(flash, 0f, Time.deltaTime * 3f));
        }
    }
}

