Shader "Custom/PhotonBeam"
{
    Properties
    {
        _Color ("Color", Color) = (0.7, 1.0, 0.95, 0.9)
        _CoreColor ("Core Color", Color) = (1.0, 1.0, 1.0, 1.0)
        _BeamRadius ("Beam Radius", Float) = 0.6
        _Flash ("Flash", Range(0,1)) = 0
        _PulseSpeed ("Pulse Speed", Float) = 4
        _Opacity ("Opacity", Range(0,1)) = 0.85
    }
    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "Queue" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
        }
        Blend SrcAlpha One
        ZWrite Off
        Cull Off

        Pass
        {
            Name "Forward"
            Tags { "LightMode" = "UniversalForward" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma multi_compile_fog

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float4 _Color;
                float4 _CoreColor;
                float _BeamRadius;
                float _Flash;
                float _PulseSpeed;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                float fogFactor : TEXCOORD1;
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                OUT.fogFactor = ComputeFogFactor(IN.positionOS.z);
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                float2 centered = IN.uv - 0.5;
                float dist = length(centered) * 2.0;   // 0~1 (角落 √2)

                // 圆形硬遮罩（裁掉方形 sprite 角落）
                float circleMask = 1.0 - smoothstep(_BeamRadius, _BeamRadius + 0.05, dist);

                float t = _Time.y * _PulseSpeed;

                // 光柱核心：中心亮斑（受击闪白叠加）
                float core = exp(-dist * 6.0) * 0.9;
                core = max(core, _Flash * 0.8);

                // 光柱主体：垂直光束感（径向渐变 + 脉冲呼吸）
                float beamBody = (1.0 - smoothstep(0.0, _BeamRadius * 0.85, dist)) * 0.5;
                float pulse = 1.0 + 0.15 * sin(t + dist * 8.0);
                beamBody *= pulse;

                // 外圈光环（能量环）
                float ring = exp(-abs(dist - _BeamRadius * 0.6) * 10.0) * 0.5;

                float4 col = _CoreColor * core * 1.5;
                col += _Color * beamBody;
                col += _Color * ring;

                col.a = (core + beamBody + ring) * _Opacity * circleMask;

                if (col.a < 0.01) discard;

                col.rgb = MixFog(col.rgb, IN.fogFactor);
                return col;
            }
            ENDHLSL
        }

        Pass
        {
            Name "Forward2D"
            Tags { "LightMode" = "Universal2D" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float4 _Color;
                float4 _CoreColor;
                float _BeamRadius;
                float _Flash;
                float _PulseSpeed;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                float2 centered = IN.uv - 0.5;
                float dist = length(centered) * 2.0;

                float circleMask = 1.0 - smoothstep(_BeamRadius, _BeamRadius + 0.05, dist);

                float t = _Time.y * _PulseSpeed;

                float core = exp(-dist * 6.0) * 0.9;
                core = max(core, _Flash * 0.8);

                float beamBody = (1.0 - smoothstep(0.0, _BeamRadius * 0.85, dist)) * 0.5;
                float pulse = 1.0 + 0.15 * sin(t + dist * 8.0);
                beamBody *= pulse;

                float ring = exp(-abs(dist - _BeamRadius * 0.6) * 10.0) * 0.5;

                float4 col = _CoreColor * core * 1.5;
                col += _Color * beamBody;
                col += _Color * ring;

                col.a = (core + beamBody + ring) * _Opacity * circleMask;

                if (col.a < 0.01) discard;

                return col;
            }
            ENDHLSL
        }
    }
    FallBack "Sprites/Default"
}

args.script:
using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/PhotonRadiance";
string dataDir = "Assets/Resources/Skills/Data/PhotonRadiance";
if (!AssetDatabase.IsValidFolder(skillDir))
    AssetDatabase.CreateFolder("Assets/Prefabs/SkillAsset", "PhotonRadiance");
if (!AssetDatabase.IsValidFolder(dataDir))
    AssetDatabase.CreateFolder("Assets/Resources/Skills/Data", "PhotonRadiance");

// ── 1. 材质 ──
Shader shader = Shader.Find("Custom/PhotonBeam");
if (shader == null) { Debug.LogError("PhotonBeam shader 未找到!"); return; }
string matPath = skillDir + "/PhotonBeam.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetColor("_Color", new Color(0.7f, 1.0f, 0.95f, 0.9f));   // 青白光柱
mat.SetColor("_CoreColor", new Color(1.0f, 1.0f, 1.0f, 1.0f));
mat.SetFloat("_BeamRadius", 0.6f);
mat.SetFloat("_Flash", 0f);
mat.SetFloat("_PulseSpeed", 4f);
mat.SetFloat("_Opacity", 0.85f);
EditorUtility.SetDirty(mat);
Debug.Log("材质: " + matPath);

// ── 2. 光柱预制体 ──
string prefabPath = skillDir + "/PhotonBeam.prefab";
GameObject existing = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
if (existing == null)
{
    var go = new GameObject("PhotonBeam");
    var sr = go.AddComponent<SpriteRenderer>();
    sr.material = mat;
    sr.sortingOrder = 40;

    // 1x1 白色 sprite（PPU=1，scale 即直径）
    var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
    tex.SetPixel(0, 0, Color.white);
    tex.Apply();
    sr.sprite = Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);

    // 光柱尺寸：伤害半径 1.2 → scale 2.4
    go.transform.localScale = new Vector3(2.4f, 2.4f, 1f);

    // 伤害组件（参数 Inspector 默认）
    var beam = go.AddComponent<PhotonBeam>();
    var so = new SerializedObject(beam);
    so.FindProperty("_radius").floatValue = 1.2f;
    so.FindProperty("_baseDamage").floatValue = 20f;
    so.FindProperty("_tickInterval").floatValue = 0.3f;
    so.FindProperty("_maxTicks").intValue = 8;
    so.ApplyModifiedProperties();

    var saved = PrefabUtility.SaveAsPrefabAsset(go, prefabPath);
    Debug.Log("预制体: " + (saved != null ? prefabPath : "保存失败"));
    Object.DestroyImmediate(go);
}
else
{
    Debug.Log("预制体已存在: " + prefabPath);
}

// ── 3. Effect SO（SummonSkillEffect 配置）──
string effectPath = dataDir + "/PhotonRadianceEffect.asset";
SummonSkillEffect effect = AssetDatabase.LoadAssetAtPath<SummonSkillEffect>(effectPath);
if (effect == null)
{
    effect = ScriptableObject.CreateInstance<SummonSkillEffect>();
    AssetDatabase.CreateAsset(effect, effectPath);
}
effect.playerMinionPrefabs = new[] { AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath) };
effect.enemyMinionPrefabs = new[] { AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath) };
effect.count = 5;                     // 5 道光柱
effect.spawnRadius = 6f;
effect.spawnInterval = 0.08f;         // 快速生成
effect.preferEnemySpawn = true;       // 高概率在敌方坐标
effect.enemySpawnChance = 0.9f;
EditorUtility.SetDirty(effect);
Debug.Log("Effect: " + effectPath);

// ── 4. SkillData ──
string dataPath = dataDir + "/PhotonRadiance.asset";
SkillData sd = AssetDatabase.LoadAssetAtPath<SkillData>(dataPath);
if (sd == null)
{
    sd = ScriptableObject.CreateInstance<SkillData>();
    AssetDatabase.CreateAsset(sd, dataPath);
}
sd.skillId = "photon_radiance";
sd.skillName = "线粒体生物光子辐散";
sd.description = "释放瞬间在房间内随机生成5道垂直能量光柱，极高概率直接生成在敌方单位坐标。每道光柱对范围内敌人造成最多8段伤害（单段=20+100%攻击力）。光柱不会伤害玩家、仆从、己方弹幕；多道光柱可同时命中同一敌人，伤害独立分段结算。";
sd.cooldown = 15f;
sd.castRange = 0f;
sd.damageMultiplier = 1f;
sd.maxLevel = 5;
sd.skillEffect = effect;
sd.icon = null;
EditorUtility.SetDirty(sd);
Debug.Log("SkillData: " + dataPath);

// ── 5. 注册 ──
SkillLibrary lib = AssetDatabase.LoadAssetAtPath<SkillLibrary>("Assets/Resources/Skills/SkillLibrary.asset");
bool found = false;
foreach (var s in lib.AllSkills)
{
    if (s != null && s.skillId == "photon_radiance") { found = true; break; }
}
if (!found)
{
    var field = typeof(SkillLibrary).GetField("_allSkills",
        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var list = field.GetValue(lib) as System.Collections.Generic.List<SkillData>;
    if (list != null)
    {
        list.Add(sd);
        Debug.Log("已注册到 SkillLibrary");
    }
    EditorUtility.SetDirty(lib);
}
else Debug.Log("已在 SkillLibrary 中");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
