using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    var enemies = Object.FindObjectsOfType<EnemyCore>();
    if (enemies.Length == 0) { Debug.LogError("无敌人!"); yield break; }
    var enemy = enemies[0];
    enemy.transform.position = new Vector3(3, 1, 0);
    enemy.Health.MaxHealth = 1000f;
    enemy.Health.Heal(1000f);
    yield return new WaitForSeconds(0.2f);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "photon_radiance");
    if (sd == null) { Debug.LogError("photon_radiance 未找到!"); yield break; }
    Debug.Log($"技能: {sd.skillName}, effect: {sd.skillEffect?.GetType().Name}");

    // 施放（5 道光柱，0.08s 间隔 → 0.4s 生成完）
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);
    Debug.Log("已施放");

    yield return new WaitForSeconds(1.0f);

    // 检查光柱数量
    var beams = Object.FindObjectsOfType<PhotonBeam>();
    Debug.Log($"光柱数量: {beams.Length} (应 5)");

    // 检查光柱是否生成在敌人附近（高概率）
    if (beams.Length > 0)
    {
        int nearEnemy = 0;
        foreach (var b in beams)
        {
            float d = Vector2.Distance(b.transform.position, enemy.transform.position);
            if (d < 1.5f) nearEnemy++;
        }
        Debug.Log($"落在敌人附近(1.5内)的光柱: {nearEnemy}/{beams.Length} (高概率应在敌人处)");
    }

    // 检查敌人受伤（8 段 × (20+攻击20) = 最多 320）
    Debug.Log($"敌人生命: {enemy.Health.CurrentHealth} (1000 - 已结算伤害)");
}

return Run();

