private void Start()
{
    // 2.5D 竖立光柱：地面光斑（圆形）+ 竖立柱体（垂直向上）+ 顶部辉光
    SetupVisual();

    // 启动伤害 tick 协程（若未被外部 Initialize 则用默认值）
    StartCoroutine(TickRoutine());
}

/// <summary>构建 2.5D 竖立光柱视觉（以撒式）</summary>
private void SetupVisual()
{
    // 1. 地面光斑（本对象 SpriteRenderer，俯视圆形）
    _sr = GetComponent<SpriteRenderer>();
    if (_sr != null && _sr.material != null)
    {
        _matInstance = new Material(_sr.sharedMaterial);
        _sr.material = _matInstance;
    }
    if (_sr != null && _sr.sprite == null)
        _sr.sprite = CreateWhiteSprite();

    // 2. 竖立柱体（子对象，垂直向上的发光柱）
    //    2.5D 表现：细长柱 Sprite 竖立（宽 0.5 高 3），底部在地面光斑中心
    var columnMat = Resources.Load<Material>("SkillAsset/PhotonRadiance/PhotonBeamColumn");
    if (columnMat == null)
    {
        // 兜底：用主材质
        columnMat = _matInstance != null ? _matInstance : null;
    }

    var columnGO = new GameObject("BeamColumn");
    columnGO.transform.SetParent(transform, false);
    columnGO.transform.localPosition = Vector3.zero;

    var colSr = columnGO.AddComponent<SpriteRenderer>();
    if (columnMat != null)
        colSr.material = new Material(columnMat);
    colSr.sprite = CreateWhiteSprite();
    colSr.sortingOrder = 41;   // 光柱本体在光斑之上

    // 柱体尺寸：宽 0.5、高 3（Sprite 1x1，scale 控制）
    float width = 0.5f;
    float height = 3.0f;
    columnGO.transform.localScale = new Vector3(width, height, 1f);
    // 底部对齐到光斑中心（Sprite pivot 在中心 → 下移半高）
    columnGO.transform.localPosition = new Vector3(0f, -height * 0.5f, 0f);

    _columnTransform = columnGO.transform;
    _columnRenderer = colSr;
    if (colSr.material != null)
        _columnMat = colSr.material;

    // 初始脉冲参数
    if (_columnMat != null)
    {
        _columnMat.SetFloat("_Height", height);
        _columnMat.SetFloat("_Width", width);
        _columnMat.SetFloat("_Flash", 0f);
    }
}

/// <summary>生成纯白 1x1 sprite（PPU=1）</summary>
private static Sprite CreateWhiteSprite()
{
    var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
    tex.SetPixel(0, 0, Color.white);
    tex.Apply();
    return Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
}

