            float breath = 1f + 0.06f * Mathf.Sin(Time.time * 5f);
            Vector3 s = _columnTransform.localScale;
            _columnTransform.localScale = new Vector3(s.x, 3f * breath, s.z);
            // 底部对齐：保持柱底在地面
            _columnTransform.localPosition = new Vector3(0f, -3f * breath * 0.5f, 0f);
        }
    }
}

