using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    var enemy = Object.FindObjectsOfType<EnemyCore>()[0];
    enemy.transform.position = new Vector3(3, 1, 0);
    enemy.Health.MaxHealth = 1000f;
    enemy.Health.Heal(1000f);
    yield return new WaitForSeconds(0.2f);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "photon_radiance");
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);

    yield return new WaitForSeconds(0.5f);

    var beams = Object.FindObjectsOfType<PhotonBeam>();
    Debug.Log($"光柱: {beams.Length}");
    if (beams.Length > 0)
    {
        // 检查柱体子对象
        var column = beams[0].transform.Find("BeamColumn");
        Debug.Log($"柱体子对象: {(column != null ? "存在" : "无")}");
        if (column != null)
        {
            Debug.Log($"柱体 scale: {column.localScale}, 位置: {column.localPosition}");
            var colSr = column.GetComponent<SpriteRenderer>();
            Debug.Log($"柱体材质: {colSr.sharedMaterial?.shader?.name}");
        }
    }

    // 截图
    UnityTcp.Editor.Tools.ManageScreenshot.BeginCapture(1f);
    yield return new WaitForSeconds(0.05f);
    string path = UnityTcp.Editor.Tools.ManageScreenshot.EndCaptureToGif(
        System.IO.Path.Combine(Application.dataPath, "../screenshots/PhotonColumn.png"), 1, 128);
    Debug.Log($"截图: {path}");
}

return Run();

