Shader "Custom/PhotonBeamColumn"
{
    Properties
    {
        _Color ("Color", Color) = (0.7, 1.0, 0.95, 0.9)
        _CoreColor ("Core Color", Color) = (1.0, 1.0, 1.0, 1.0)
        _Height ("Column Height", Float) = 3.0
        _Width ("Column Width", Float) = 0.5
        _Flash ("Flash", Range(0,1)) = 0
        _PulseSpeed ("Pulse Speed", Float) = 4
        _Opacity ("Opacity", Range(0,1)) = 0.9
    }
    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "Queue" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
        }
        Blend SrcAlpha One
        ZWrite Off
        Cull Off

        Pass
        {
            Name "Forward"
            Tags { "LightMode" = "UniversalForward" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma multi_compile_fog

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float4 _Color;
                float4 _CoreColor;
                float _Height;
                float _Width;
                float _Flash;
                float _PulseSpeed;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                float fogFactor : TEXCOORD1;
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                OUT.fogFactor = ComputeFogFactor(IN.positionOS.z);
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                // UV 中心化：光柱从中心(0,0)向斜上方(+y)延伸
                float2 centered = IN.uv - 0.5;
                float t = _Time.y * _PulseSpeed;

                // 柱体：x 窄、y 高 → 竖立光束造型（俯视下呈竖长条）
                float halfW = _Width * 0.5;
                float xDist = abs(centered.x);

                // 柱体遮罩（宽度内）
                float columnMask = 1.0 - smoothstep(halfW * 0.7, halfW, xDist);

                // 高度：向上渐弱 + 底部实（竖立感）
                float y = centered.y + 0.5;   // 0=底部, 1=顶部
                float topFade = 1.0 - y * 0.6;

                // 向上流动的柱体能量
                float flow = 0.5 + 0.5 * sin(y * 8.0 - t * 2.5);
                float columnBody = columnMask * topFade * (0.55 + 0.45 * flow);

                // 底部光斑（柱根）
                float baseGlow = exp(-y * 16.0) * columnMask * 1.1;

                // 顶部辉光（柱顶亮斑，竖立顶端）
                float topGlow = exp(-abs(y - 0.98) * 14.0) * columnMask * 1.3;

                // 受击闪白
                float flashBoost = _Flash;

                float4 col = _Color * columnBody;
                col += _CoreColor * topGlow;
                col += _CoreColor * baseGlow * 0.9;
                col.rgb += float3(1, 1, 1) * flashBoost * 0.6;

                col.a = (columnBody + topGlow + baseGlow) * _Opacity;

                if (col.a < 0.01) discard;

                col.rgb = MixFog(col.rgb, IN.fogFactor);
                return col;
            }
            ENDHLSL
        }

        Pass
        {
            Name "Forward2D"
            Tags { "LightMode" = "Universal2D" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float4 _Color;
                float4 _CoreColor;
                float _Height;
                float _Width;
                float _Flash;
                float _PulseSpeed;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                float2 centered = IN.uv - 0.5;
                float t = _Time.y * _PulseSpeed;

                float halfW = _Width * 0.5;
                float xDist = abs(centered.x);
                float columnMask = 1.0 - smoothstep(halfW * 0.7, halfW, xDist);

                float y = centered.y + 0.5;
                float topFade = 1.0 - y * 0.6;

                float flow = 0.5 + 0.5 * sin(y * 8.0 - t * 2.5);
                float columnBody = columnMask * topFade * (0.55 + 0.45 * flow);

                float baseGlow = exp(-y * 16.0) * columnMask * 1.1;
                float topGlow = exp(-abs(y - 0.98) * 14.0) * columnMask * 1.3;

                float flashBoost = _Flash;

                float4 col = _Color * columnBody;
                col += _CoreColor * topGlow;
                col += _CoreColor * baseGlow * 0.9;
                col.rgb += float3(1, 1, 1) * flashBoost * 0.6;

                col.a = (columnBody + topGlow + baseGlow) * _Opacity;

                if (col.a < 0.01) discard;

                return col;
            }
            ENDHLSL
        }
    }
    FallBack "Sprites/Default"
}

