        columnGO.transform.localScale = new Vector3(width, height, 1f);
        // 光束从地面光斑中心向上延伸（顶部在天上，光源在上方）
        columnGO.transform.localPosition = new Vector3(0f, height * 0.5f, 0f);

        _columnTransform = columnGO.transform;
        _columnRenderer = colSr;
        if (colSr.material != null)
            _columnMat = colSr.material;

        // 初始脉冲参数
        if (_columnMat != null)
        {
            _columnMat.SetFloat("_Height", height);
            _columnMat.SetFloat("_Width", width);
            _columnMat.SetFloat("_Flash", 0f);
        }
    }

    /// <summary>生成纯白 1x1 sprite（PPU=1）</summary>
    private static Sprite CreateWhiteSprite()
    {
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
    }

    private IEnumerator TickRoutine()
    {
        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        float damage = _baseDamage + _attackStrength;

        while (_ticksDone < _maxTicks)
        {
            // 每段伤害
            Collider2D[] hits = Physics2D.OverlapCircleAll(transform.position, _radius, ~0);
            foreach (var hit in hits)
            {
                if (hit == null || !hit.CompareTag(targetTag)) continue;

                // 跳过死亡/已同化（同化后 tag 变 Player，天然跳过）
                var enemy = hit.GetComponent<EnemyCore>();
                if (enemy != null && enemy.IsDead) continue;

                if (hit.TryGetComponent<IDamageable>(out var d))
                    d.TakeDamage(damage);
            }

            _ticksDone++;

            // 视觉脉冲反馈（地面光斑 + 竖立柱体同步闪白）
            if (_matInstance != null)
                _matInstance.SetFloat("_Flash", 1f);
            if (_columnMat != null)
                _columnMat.SetFloat("_Flash", 1f);

            yield return new WaitForSeconds(_tickInterval);
        }

        Destroy(gameObject);
    }

    private void Update()
    {
        if (!_initialized) return;

        // 地面光斑闪白衰减
        if (_matInstance != null)
        {
            float flash = _matInstance.GetFloat("_Flash");
            if (flash > 0f)
                _matInstance.SetFloat("_Flash", Mathf.MoveTowards(flash, 0f, Time.deltaTime * 3f));
        }

        // 竖立柱体：呼吸脉冲（轻微上下缩放）+ 闪白同步
        if (_columnMat != null)
        {
            float colFlash = _columnMat.GetFloat("_Flash");
            if (colFlash > 0f)
                _columnMat.SetFloat("_Flash", Mathf.MoveTowards(colFlash, 0f, Time.deltaTime * 3f));
        }

        if (_columnTransform != null)
        {
            // 高度轻微呼吸（能量脉动）—— 保留宽度，只动高度
            float breath = 1f + 0.06f * Mathf.Sin(Time.time * 5f);
            Vector3 s = _columnTransform.localScale;
            _columnTransform.localScale = new Vector3(s.x, s.y * breath, s.z);
            // 底部对齐：光束底部贴光斑中心，向上（天上）延伸
            _columnTransform.localPosition = new Vector3(0f, s.y * breath * 0.5f, 0f);
        }
    }
}

