using System.Collections;
using UnityEngine;

/// <summary>
/// 线粒体生物光子辐散 — 天降能量光柱组件。
/// 3 阶段干净特效：
///   1. 预警：落点出现清晰瞄准环（收缩脉冲），约 0.5s
///   2. 落下：光束从天而降（细亮柱 + 顶部光源 + 落地闪光扩散环）
///   3. 持续：聚焦光束对范围内敌人造成 maxTicks 段伤害（单段 = baseDamage + 攻击力）
/// 只伤害敌方阵营（tag 过滤），天然不伤害玩家、仆从、己方弹幕。
/// </summary>
public class PhotonBeam : MonoBehaviour
{
    [Header("光柱配置")]
    [Tooltip("伤害半径")]
    [SerializeField] private float _radius = 1.2f;
    [Tooltip("单段基础伤害（再加施法者攻击力）")]
    [SerializeField] private float _baseDamage = 20f;
    [Tooltip("每段伤害间隔（秒）")]
    [SerializeField] private float _tickInterval = 0.3f;
    [Tooltip("最大伤害段数（8=8段）")]
    [SerializeField] private int _maxTicks = 8;
    [Tooltip("预警时长（秒）：落点瞄准环显示时间")]
    [SerializeField] private float _warnDuration = 0.5f;
    [Tooltip("光束落点材质（圆形光斑/瞄准环）")]
    [SerializeField] private Material _beamMaterial;

    // ── 运行时状态 ──
    private Projectile.OwnerType _ownerType;
    private float _attackStrength;
    private int _ticksDone;
    private bool _initialized;
    private bool _struck;      // 是否已落下

    // ── 视觉 ──
    private SpriteRenderer _warningRing;     // 预警瞄准环
    private Material _warningMat;
    private SpriteRenderer _beamSprite;      // 持续光柱（聚焦光束）
    private Material _beamMat;

    /// <summary>初始化光柱</summary>
    public void Initialize(Projectile.OwnerType ownerType, float attackStrength)
    {
        _ownerType = ownerType;
        _attackStrength = attackStrength;
        _initialized = true;
    }

    private void Start()
    {
        CreateVisuals();
        StartCoroutine(BeamSequence());
    }

    // ──────────────────────────────────────────────
    //  视觉构建
    // ──────────────────────────────────────────────

    private void CreateVisuals()
    {
        Material baseMat = _beamMaterial;
        if (baseMat == null)
            baseMat = GetComponent<SpriteRenderer>()?.sharedMaterial;

        // 1. 预警瞄准环（落点圆圈，清晰醒目）
        var warnGO = new GameObject("WarningRing");
        warnGO.transform.SetParent(transform, false);
        warnGO.transform.localPosition = Vector3.zero;
        warnGO.transform.localScale = new Vector3(_radius * 2f, _radius * 2f, 1f);

        _warningRing = warnGO.AddComponent<SpriteRenderer>();
        if (baseMat != null)
        {
            _warningMat = new Material(baseMat);
            _warningRing.material = _warningMat;
        }
        _warningRing.sprite = CreateWhiteSprite();
        _warningRing.sortingOrder = 30;
        _warningRing.enabled = false;   // 预警时才显示

        // 2. 聚焦光束（落点核心光柱，细亮柱）
        var beamGO = new GameObject("BeamCore");
        beamGO.transform.SetParent(transform, false);
        beamGO.transform.localPosition = Vector3.zero;
        beamGO.transform.localScale = new Vector3(_radius * 1.2f, 1f, 1f);

        _beamSprite = beamGO.AddComponent<SpriteRenderer>();
        if (baseMat != null)
        {
            _beamMat = new Material(baseMat);
            _beamSprite.material = _beamMat;
        }
        _beamSprite.sprite = CreateWhiteSprite();
        _beamSprite.sortingOrder = 40;
        _beamSprite.enabled = false;   // 落下后才显示

        // 清理主对象上可能残留的 SpriteRenderer（改用子对象控制）
        var mainSr = GetComponent<SpriteRenderer>();
        if (mainSr != null)
            mainSr.enabled = false;
    }

    /// <summary>生成纯白 1x1 sprite（PPU=1）</summary>
    private static Sprite CreateWhiteSprite()
    {
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
    }

    // ──────────────────────────────────────────────
    //  3 阶段序列
    // ──────────────────────────────────────────────

    private IEnumerator BeamSequence()
    {
        // ── 阶段 1：预警（瞄准环收缩脉冲）──
        _warningRing.enabled = true;
        float warnTimer = 0f;
        while (warnTimer < _warnDuration)
        {
            warnTimer += Time.deltaTime;
            float t = warnTimer / _warnDuration;

            // 瞄准环：从 1.4x 收缩到 1x + 脉冲闪烁
            float pulse = 1f + 0.15f * Mathf.Sin(t * 20f);
            float scale = Mathf.Lerp(1.4f, 1f, t) * pulse;
            _warningRing.transform.localScale = new Vector3(
                _radius * 2f * scale, _radius * 2f * scale, 1f);

            if (_warningMat != null)
                _warningMat.SetFloat("_Flash", 0.5f + 0.5f * Mathf.Sin(t * 20f));

            yield return null;
        }

        // ── 阶段 2：落下（光束瞬间降下 + 落地闪光）──
        _warningRing.enabled = false;
        _beamSprite.enabled = true;
        _struck = true;

        // 光束：从天而降（从高处快速落下，配合缩放）
        // 用 y 缩放模拟从天而降：从顶部快速压到落地
        float fallTime = 0.18f;
        float fallTimer = 0f;
        Vector3 baseScale = new Vector3(_radius * 1.2f, 1f, 1f);
        while (fallTimer < fallTime)
        {
            fallTimer += Time.deltaTime;
            float t = fallTimer / fallTime;
            float ease = 1f - Mathf.Pow(1f - t, 3f);   // easeOutCubic 快速落下

            // 光束高度：从天(高)落到地(1x)
            float h = Mathf.Lerp(5f, 1f, ease);
            _beamSprite.transform.localScale = new Vector3(baseScale.x, h, 1f);
            // 顶部对齐：光源在天上（顶部固定，底部向下延伸）
            _beamSprite.transform.localPosition = new Vector3(0f, h * 0.5f, 0f);

            if (_beamMat != null)
                _beamMat.SetFloat("_Flash", 1f - t);

            yield return null;
        }
        _beamSprite.transform.localScale = baseScale;
        _beamSprite.transform.localPosition = Vector3.zero;

        // 落地闪光（扩散环，瞬间张力）
        SpawnImpactFlash();

        // ── 阶段 3：持续伤害（8 段）──
        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        float damage = _baseDamage + _attackStrength;

        while (_ticksDone < _maxTicks)
        {
            // 每段伤害
            Collider2D[] hits = Physics2D.OverlapCircleAll(transform.position, _radius, ~0);
            foreach (var hit in hits)
            {
                if (hit == null || !hit.CompareTag(targetTag)) continue;

                var enemy = hit.GetComponent<EnemyCore>();
                if (enemy != null && enemy.IsDead) continue;

                if (hit.TryGetComponent<IDamageable>(out var d))
                    d.TakeDamage(damage);
            }

            _ticksDone++;

            // 命中脉冲：光束闪白 + 轻微放大
            if (_beamMat != null)
                _beamMat.SetFloat("_Flash", 1f);
            _beamSprite.transform.localScale = baseScale * 1.15f;
            yield return new WaitForSeconds(0.06f);
            _beamSprite.transform.localScale = baseScale;

            yield return new WaitForSeconds(Mathf.Max(_tickInterval - 0.06f, 0.05f));
        }

        // 结束：光束淡出
        if (_beamMat != null)
            _beamMat.SetFloat("_Flash", 0f);
        yield return new WaitForSeconds(0.1f);

        Destroy(gameObject);
    }

    /// <summary>落地闪光（扩散环，干净张力）</summary>
    private void SpawnImpactFlash()
    {
        var flashGO = new GameObject("ImpactFlash");
        flashGO.transform.SetParent(transform, false);
        flashGO.transform.localPosition = Vector3.zero;

        var sr = flashGO.AddComponent<SpriteRenderer>();
        if (_beamMaterial != null)
            sr.material = new Material(_beamMaterial);
        sr.sprite = CreateWhiteSprite();
        sr.sortingOrder = 35;

        // 快速扩散 + 淡出（0.25s）
        var anim = flashGO.AddComponent<ImpactFlashAnimator>();
        anim.Init(_radius);
    }

    /// <summary>落地闪光动画</summary>
    private class ImpactFlashAnimator : MonoBehaviour
    {
        private float _radius;
        private float _timer;
        private const float Duration = 0.25f;
        private SpriteRenderer _sr;
        private Material _mat;

        public void Init(float radius)
        {
            _radius = radius;
            _sr = GetComponent<SpriteRenderer>();
            _mat = _sr.material;
        }

        private void Update()
        {
            _timer += Time.deltaTime;
            float t = Mathf.Clamp01(_timer / Duration);

            // 快速扩散（0.8x → 2.5x 半径）
            float scale = Mathf.Lerp(_radius * 0.8f, _radius * 2.5f, t);
            transform.localScale = new Vector3(scale * 2f, scale * 2f, 1f);

            if (_mat != null)
                _mat.SetFloat("_Flash", 1f - t);

            if (t >= 1f)
                Destroy(gameObject);
        }
    }

    private void Update()
    {
        if (!_initialized || !_struck) return;

        // 光束闪白衰减 + 轻微呼吸
        if (_beamMat != null)
        {
            float flash = _beamMat.GetFloat("_Flash");
            if (flash > 0f)
                _beamMat.SetFloat("_Flash", Mathf.MoveTowards(flash, 0f, Time.deltaTime * 3f));
        }

        // 聚焦光束轻微呼吸（张力保持）
        if (_beamSprite != null)
        {
            float breath = 1f + 0.04f * Mathf.Sin(Time.time * 6f);
            Vector3 s = _beamSprite.transform.localScale;
            _beamSprite.transform.localScale = new Vector3(s.x, s.y, breath * s.z);
        }
    }
}

Shader "Custom/PhotonBeamCore"
{
    Properties
    {
        _Color ("Color", Color) = (0.9, 0.5, 0.35, 1.0)      // 预警橙/落点色
        _CoreColor ("Core Color", Color) = (1.0, 0.85, 0.6, 1.0)
        _Mode ("Mode", Float) = 0        // 0=瞄准环, 1=光束, 2=闪光
        _Flash ("Flash", Range(0,1)) = 0
        _Opacity ("Opacity", Range(0,1)) = 0.9
    }
    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "Queue" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
        }
        Blend SrcAlpha One
        ZWrite Off
        Cull Off

        Pass
        {
            Name "Forward"
            Tags { "LightMode" = "UniversalForward" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma multi_compile_fog

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float4 _Color;
                float4 _CoreColor;
                float _Mode;
                float _Flash;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                float fogFactor : TEXCOORD1;
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                OUT.fogFactor = ComputeFogFactor(IN.positionOS.z);
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                float2 centered = IN.uv - 0.5;
                float dist = length(centered) * 2.0;

                // 圆形硬遮罩（裁掉方形角落）
                float circleMask = 1.0 - smoothstep(0.95, 1.0, dist);

                float4 col = 0;

                if (_Mode < 0.5)
                {
                    // ── 瞄准环：清晰细环 + 中心点 + 十字标记 ──
                    float ring = 1.0 - smoothstep(0.0, 0.045, abs(dist - 0.72));
                    float innerDot = 1.0 - smoothstep(0.0, 0.1, dist);
                    // 十字线
                    float crossH = 1.0 - smoothstep(0.0, 0.02, abs(centered.x)) ;
                    float crossV = 1.0 - smoothstep(0.0, 0.02, abs(centered.y));
                    float cross = max(crossH, crossV) * (1.0 - smoothstep(0.0, 0.35, dist));

                    col = _Color * (ring * 1.2 + innerDot * 0.5 + cross * 0.4);
                    col.a = (ring + innerDot * 0.5 + cross * 0.4) * _Opacity * circleMask;
                }
                else if (_Mode < 1.5)
                {
                    // ── 光束：竖直细亮柱（从天而降聚焦光束）──
                    float xDist = abs(centered.x);
                    float beam = 1.0 - smoothstep(0.0, 0.18, xDist);
                    // 中心亮核
                    float core = exp(-dist * 8.0) * 0.8;

                    col = _Color * beam * 0.8 + _CoreColor * core;
                    col.a = (beam * 0.8 + core) * _Opacity * circleMask;
                }
                else
                {
                    // ── 闪光：径向扩散亮斑 ──
                    float glow = exp(-dist * 5.0);
                    col = _CoreColor * glow;
                    col.a = glow * _Opacity * circleMask;
                }

                // 闪白（预警闪烁/命中脉冲）
                col.rgb = lerp(col.rgb, float3(1, 1, 1), _Flash);

                if (col.a < 0.01) discard;

                col.rgb = MixFog(col.rgb, IN.fogFactor);
                return col;
            }
            ENDHLSL
        }

        Pass
        {
            Name "Forward2D"
            Tags { "LightMode" = "Universal2D" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            CBUFFER_START(UnityPerMaterial)
                float4 _Color;
                float4 _CoreColor;
                float _Mode;
                float _Flash;
                float _Opacity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = IN.uv;
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                float2 centered = IN.uv - 0.5;
                float dist = length(centered) * 2.0;

                float circleMask = 1.0 - smoothstep(0.95, 1.0, dist);

                float4 col = 0;

                if (_Mode < 0.5)
                {
                    float ring = 1.0 - smoothstep(0.0, 0.045, abs(dist - 0.72));
                    float innerDot = 1.0 - smoothstep(0.0, 0.1, dist);
                    float crossH = 1.0 - smoothstep(0.0, 0.02, abs(centered.x));
                    float crossV = 1.0 - smoothstep(0.0, 0.02, abs(centered.y));
                    float cross = max(crossH, crossV) * (1.0 - smoothstep(0.0, 0.35, dist));

                    col = _Color * (ring * 1.2 + innerDot * 0.5 + cross * 0.4);
                    col.a = (ring + innerDot * 0.5 + cross * 0.4) * _Opacity * circleMask;
                }
                else if (_Mode < 1.5)
                {
                    float xDist = abs(centered.x);
                    float beam = 1.0 - smoothstep(0.0, 0.18, xDist);
                    float core = exp(-dist * 8.0) * 0.8;

                    col = _Color * beam * 0.8 + _CoreColor * core;
                    col.a = (beam * 0.8 + core) * _Opacity * circleMask;
                }
                else
                {
                    float glow = exp(-dist * 5.0);
                    col = _CoreColor * glow;
                    col.a = glow * _Opacity * circleMask;
                }

                col.rgb = lerp(col.rgb, float3(1, 1, 1), _Flash);

                if (col.a < 0.01) discard;

                return col;
            }
            ENDHLSL
        }
    }
    FallBack "Sprites/Default"
}

