args.script:
using UnityEditor;
using UnityEngine;

string skillDir = "Assets/Prefabs/SkillAsset/PhotonRadiance";

// ── 1. 核心材质（瞄准环/光束/闪光三用）──
Shader shader = Shader.Find("Custom/PhotonBeamCore");
if (shader == null) { Debug.LogError("PhotonBeamCore shader 未找到!"); return; }

string matPath = skillDir + "/PhotonBeamCore.mat";
Material mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetColor("_Color", new Color(0.95f, 0.55f, 0.3f, 1.0f));     // 预警橙
mat.SetColor("_CoreColor", new Color(1.0f, 0.9f, 0.7f, 1.0f));
mat.SetFloat("_Mode", 0f);
mat.SetFloat("_Flash", 0f);
mat.SetFloat("_Opacity", 0.9f);
EditorUtility.SetDirty(mat);
Debug.Log("核心材质: " + matPath);

// ── 2. 绑定到光柱预制体 ──
string prefabPath = skillDir + "/PhotonBeam.prefab";
var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
if (prefab != null)
{
    var beam = prefab.GetComponent<PhotonBeam>();
    if (beam != null)
    {
        var so = new SerializedObject(beam);
        so.FindProperty("_beamMaterial").objectReferenceValue = mat;
        so.ApplyModifiedProperties();
        EditorUtility.SetDirty(prefab);
        Debug.Log("核心材质已绑定到光柱预制体");
    }
}

AssetDatabase.SaveAssets();
Debug.Log("=== 完成 ===");

