using UnityEngine;

/// <summary>
/// 能量辐射池 — 光柱落下后原地遗留的辐射区域。
/// 给进入圈内的敌人持续施加"能量辐射"debuff（持续伤害），
/// 目标在圈内停留会刷新 debuff 时长（BuffManager.ApplyBuff 的 Refresh 行为）。
/// duration 秒后辐射池消散。只影响敌方阵营（ownerType 决定）。
/// </summary>
public class PhotonRadiancePool : MonoBehaviour
{
    [Header("辐射池配置")]
    [Tooltip("作用半径")]
    [SerializeField] private float _radius = 1.5f;
    [Tooltip("持续时间（秒），到时消散")]
    [SerializeField] private float _duration = 10f;
    [Tooltip("检测/刷新间隔（秒）")]
    [SerializeField] private float _refreshInterval = 0.25f;
    [Tooltip("给目标挂的持续伤害 debuff（DamageOverTimeBuff，Refresh 行为）")]
    [SerializeField] private BuffData _debuffData;

    // ── 运行时状态 ──
    private Projectile.OwnerType _ownerType;
    private GameObject _casterGO;
    private float _timer;
    private float _nextRefreshTime;
    private bool _initialized;

    // ── 视觉 ──
    private SpriteRenderer _sr;
    private Material _matInstance;

    /// <summary>初始化辐射池</summary>
    public void Initialize(Projectile.OwnerType ownerType, GameObject caster, float radius, float duration)
    {
        _ownerType = ownerType;
        _casterGO = caster;
        _radius = radius;
        _duration = duration;
        _initialized = true;
    }

    private void Start()
    {
        // 视觉：辐射池（主对象 SpriteRenderer）
        _sr = GetComponent<SpriteRenderer>();
        if (_sr != null && _sr.material != null)
        {
            _matInstance = new Material(_sr.sharedMaterial);
            _sr.material = _matInstance;
        }
        // 修复：预制体保存时 sprite 引用丢失
        if (_sr != null && _sr.sprite == null)
            _sr.sprite = CreateWhiteSprite();

        // 辐射池尺寸 = 半径
        transform.localScale = new Vector3(_radius * 2f, _radius * 2f, 1f);

        _timer = _duration;
        _nextRefreshTime = Time.time + _refreshInterval;
    }

    private void Update()
    {
        if (!_initialized) return;

        _timer -= Time.deltaTime;
        if (_timer <= 0f)
        {
            // 消散（快速淡出）
            Destroy(gameObject);
            return;
        }

        // 辐射池呼吸脉冲
        if (_matInstance != null)
        {
            float breath = 1f + 0.06f * Mathf.Sin(Time.time * 4f);
            transform.localScale = new Vector3(_radius * 2f * breath, _radius * 2f * breath, 1f);
        }

        // 周期给圈内敌人挂 debuff（Refresh 行为 → 停留刷新）
        if (Time.time >= _nextRefreshTime)
        {
            _nextRefreshTime = Time.time + _refreshInterval;
            RefreshDebuffs();
        }
    }

    /// <summary>给圈内敌方目标应用/刷新 debuff</summary>
    private void RefreshDebuffs()
    {
        if (_debuffData == null) return;

        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";

        Collider2D[] hits = Physics2D.OverlapCircleAll(transform.position, _radius, ~0);
        foreach (var hit in hits)
        {
            if (hit == null || !hit.CompareTag(targetTag)) continue;

            // 跳过死亡/已同化
            var enemy = hit.GetComponent<EnemyCore>();
            if (enemy != null && (enemy.IsDead || enemy.IsAssimilated)) continue;

            var buffMgr = hit.GetComponent<BuffManager>();
            if (buffMgr == null) continue;

            buffMgr.ApplyBuff(_debuffData, _casterGO);
        }
    }

    /// <summary>生成纯白 1x1 sprite（PPU=1）</summary>
    private static Sprite CreateWhiteSprite()
    {
        var tex = new Texture2D(1, 1, TextureFormat.RGBA32, false);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
    }
}

