using UnityEditor;
using UnityEngine;

string dataDir = "Assets/Resources/Skills/Data/PhotonRadiance";

// ── 1. DOT effect 资产（复用 DamageOverTimeBuff）──
string dotPath = dataDir + "/PhotonRadianceDOTEffect.asset";
DamageOverTimeBuff dotEffect = AssetDatabase.LoadAssetAtPath<DamageOverTimeBuff>(dotPath);
if (dotEffect == null)
{
    dotEffect = ScriptableObject.CreateInstance<DamageOverTimeBuff>();
    AssetDatabase.CreateAsset(dotEffect, dotPath);
}
dotEffect.damagePerTick = 15f;
dotEffect.tickInterval = 1f;
EditorUtility.SetDirty(dotEffect);
Debug.Log("DOT effect: " + dotPath);

// ── 2. BuffData（能量辐射 debuff）──
string buffPath = dataDir + "/PhotonRadianceDebuff.asset";
BuffData buffData = AssetDatabase.LoadAssetAtPath<BuffData>(buffPath);
if (buffData == null)
{
    buffData = ScriptableObject.CreateInstance<BuffData>();
    AssetDatabase.CreateAsset(buffData, buffPath);
}
buffData.buffId = "photon_radiance_debuff";
buffData.buffName = "能量辐射";
buffData.description = "能量辐射池持续灼烧目标，每秒造成15点伤害。在辐射池内停留会刷新持续时间。";
buffData.buffType = BuffType.Debuff;
buffData.duration = 3f;
buffData.isPermanent = false;
buffData.stackable = false;
buffData.maxStacks = 1;
buffData.stackBehavior = StackBehavior.Refresh;
buffData.effect = dotEffect;
buffData.icon = null;
EditorUtility.SetDirty(buffData);
Debug.Log("BuffData: " + buffPath);

// ── 3. 绑定到光柱预制体 ──
string prefabPath = "Assets/Prefabs/SkillAsset/PhotonRadiance/PhotonBeam.prefab";
var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
if (prefab != null)
{
    var beam = prefab.GetComponent<PhotonBeam>();
    if (beam != null)
    {
        var so = new SerializedObject(beam);
        so.FindProperty("_radianceDebuff").objectReferenceValue = buffData;
        so.FindProperty("_poolDuration").floatValue = 10f;
        so.FindProperty("_poolRadius").floatValue = 1.5f;
        so.ApplyModifiedProperties();
        EditorUtility.SetDirty(prefab);
        Debug.Log("辐射 debuff 已绑定到光柱预制体");
    }
}

AssetDatabase.SaveAssets();
Debug.Log("=== 能量辐射池资产创建完成 ===");

