using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    var enemy = Object.FindObjectsOfType<EnemyCore>()[0];
    enemy.transform.position = new Vector3(3, 0, 0);
    enemy.Health.MaxHealth = 1000f;
    enemy.Health.Heal(1000f);
    yield return new WaitForSeconds(0.2f);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "photon_radiance");
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);

    // 等光柱落下 + 辐射池生成（0.7s 落下 + 0.5s）
    yield return new WaitForSeconds(1.2f);

    var pools = Object.FindObjectsOfType<PhotonRadiancePool>();
    Debug.Log($"辐射池数量: {pools.Length} (光柱5个应有5个池)");

    // 检查敌人是否有能量辐射 debuff
    var buffMgr = enemy.GetComponent<BuffManager>();
    bool hasDebuff = buffMgr != null && buffMgr.HasBuff("photon_radiance_debuff");
    Debug.Log($"敌人有能量辐射debuff: {hasDebuff}");

    // 检查敌人持续受伤（光柱 8 段 + 辐射池 DOT）
    Debug.Log($"敌人生命: {enemy.Health.CurrentHealth}");
}

return Run();

