args.script:
using System.Collections;
using UnityEngine;
using System.Linq;

IEnumerator Run()
{
    var player = GameObject.FindGameObjectWithTag("Player");
    player.transform.position = new Vector3(0, 0, 0);

    var skillMgr = player.GetComponent<PlayerSkillManager>();
    SkillLibrary lib = Resources.Load<SkillLibrary>("Skills/SkillLibrary");
    var sd = lib.AllSkills.FirstOrDefault(s => s.skillId == "photon_radiance");
    sd.skillEffect.Execute(skillMgr, Vector2.right, 1f, Projectile.OwnerType.Player);

    // 光柱落下 + 辐射池生成（1s）
    yield return new WaitForSeconds(1.2f);

    int beams = Object.FindObjectsOfType<PhotonBeam>().Length;
    int pools = Object.FindObjectsOfType<PhotonRadiancePool>().Length;
    Debug.Log($"1.2s: 光柱={beams}, 辐射池={pools}");

    // 光柱短暂停留后应快速销毁（一次性伤害后 ~0.35s）
    yield return new WaitForSeconds(1f);
    int beams2 = Object.FindObjectsOfType<PhotonBeam>().Length;
    int pools2 = Object.FindObjectsOfType<PhotonRadiancePool>().Length;
    Debug.Log($"2.2s: 光柱={beams2} (应0, 一次性伤害后销毁), 辐射池={pools2} (应仍在)");
    Debug.Log(pools2 > 0 ? "✅ 辐射池存活（接管持续伤害）" : "⚠️ 辐射池未存活");
}

return Run();

